# RGB-derived: docs/store_laptop_and_headphones/applied_values.json (rgb_derived_values).
"""RGB updates generated by --run-geometry-fitting.

Evidence: docs/store_laptop_and_headphones/geometry_fit.json
Perception and manipulation use RGB, camera calibration, proprioception and SAM3.
"""
import math
import numpy as np
from PIL import Image, ImageDraw

RGB_GEOMETRY_EVIDENCE = 'docs/store_laptop_and_headphones/'
TABLE_PLANE = (0.0004820468828728375, -0.0008792700217863381, 0.7645898153104881)
TABLE_Z = TABLE_PLANE[2]
LID_TOP_Z = 0.963  # Observed open-lid upper edge, world z.


def _carry_z():
    """World height halfway between the measured table and the measured cradle outline."""
    return 0.5 * (float(TABLE_Z) + float(CRADLE_OUTLINE_Z))
SCREEN_PROMPT = 'laptop screen'
LAPTOP_PROMPT = 'laptop'
HEADSET_PROMPT = 'headphones'
STAND_PROMPT = 'wooden T-shaped stand'
STAND_PROMPTS = (STAND_PROMPT, 'T-shaped wooden stand with a round base', 'wooden stand with a flat base and a pole', 'headphone stand')
RACK_PROMPTS = ('small wooden rack with white dividers', 'small wooden card holder', 'small wooden rack')


def cam(robo, name='cam_head'):
    m = robo.camera_meta(name)
    return np.asarray(m['intrinsic_matrix'], float), np.asarray(m['extrinsic_matrix'], float)


def pixel_ray(K, E, rc):
    """World origin and unit direction of the ray through pixel (row, col)."""
    r, c = float(rc[0]), float(rc[1])
    d = E[:3, :3] @ np.array([(c - K[0, 2]) / K[0, 0], -(r - K[1, 2]) / K[1, 1], -1.0])
    return E[:3, 3].copy(), d / np.linalg.norm(d)


def ray_at_z(K, E, rc, z):
    o, d = pixel_ray(K, E, rc)
    return o + (z - o[2]) / d[2] * d


def project(K, E, pts):
    """World points -> (row, col) pixels."""
    P = np.atleast_2d(np.asarray(pts, float))
    pc = (P - E[:3, 3]) @ E[:3, :3]
    col = K[0, 2] + K[0, 0] * pc[:, 0] / -pc[:, 2]
    row = K[1, 2] - K[1, 1] * pc[:, 1] / -pc[:, 2]
    return np.c_[row, col]


def mask_of(seg, shape=(480, 640)):
    """Rasterize a Segment's outlines into a boolean mask."""
    im = Image.new('L', (shape[1], shape[0]), 0)
    dr = ImageDraw.Draw(im)
    for outline in seg.contours_rc or ():
        pts = [(int(c), int(r)) for r, c in outline]
        if len(pts) >= 3:
            dr.polygon(pts, fill=255)
    return np.asarray(im) > 0


def carve_holes(filled, area_px, rgb):
    """Remove enclosed background from a mask rasterized from outer outlines.

    ``robo.segment`` returns outer outlines and the true mask area. When the
    filled outline is larger than that area, the object encloses background
    (the table seen through a headband). The enclosed pixels that look most
    like the background just outside the outline are removed, up to the
    missing area.
    """
    import cv2
    extra = int(filled.sum()) - int(area_px)
    if area_px <= 0 or extra < 0.06 * filled.sum():
        return filled
    f = filled.astype(np.uint8)
    ring = (cv2.dilate(f, np.ones((15, 15), np.uint8)) > 0) & ~(cv2.dilate(f, np.ones((5, 5), np.uint8)) > 0)
    if ring.sum() < 50:
        return filled
    lab = cv2.cvtColor(np.ascontiguousarray(np.asarray(rgb)[:, :, :3]), cv2.COLOR_RGB2LAB).astype(np.float32)
    bg = lab[ring]
    mu, sd = bg.mean(axis=0), bg.std(axis=0) + 4.0
    inner = (cv2.erode(f, np.ones((3, 3), np.uint8)) > 0)
    d = np.full(filled.shape, np.inf, np.float32)
    d[inner] = np.sqrt((((lab[inner] - mu) / sd) ** 2).sum(axis=1))
    order = np.sort(d[inner])
    cut = order[min(len(order) - 1, extra)]
    hole = (d <= cut).astype(np.uint8)
    hole = cv2.morphologyEx(hole, cv2.MORPH_OPEN, np.ones((3, 3), np.uint8))
    n, labels, stats, _ = cv2.connectedComponentsWithStats(hole)
    keep = np.zeros_like(hole)
    for i in range(1, n):
        if stats[i, cv2.CC_STAT_AREA] >= max(40, 0.15 * extra):
            keep[labels == i] = 1
    return filled & ~(keep > 0)


def segment(robo, prompt, camera='cam_head', min_score=0.2):
    s = robo.segment(prompt, camera, min_score, include_contours=True)
    if not s.found:
        return None
    filled = mask_of(s)
    mask = carve_holes(filled, s.area_px, robo.image(camera))
    return dict(prompt=prompt, camera=camera, score=s.score, box=s.box, centroid=s.centroid,
                area=s.area_px, mask=mask, filled=int(filled.sum()), seg=s)


def overlay(robo, camera='cam_head', masks=(), points=(), lines=(), scale=2):
    """RGB overlay for review: mask outlines, world points/lines projected."""
    K, E = cam(robo, camera)
    im = Image.fromarray(np.asarray(robo.image(camera))).convert('RGB')
    dr = ImageDraw.Draw(im)
    cols = [(255, 0, 0), (0, 255, 0), (0, 160, 255), (255, 255, 0), (255, 0, 255), (0, 255, 255)]
    for i, m in enumerate(masks):
        if m is None:
            continue
        for outline in m['seg'].contours_rc or ():
            pts = [(int(c), int(r)) for r, c in outline]
            if len(pts) >= 3:
                dr.line(pts + [pts[0]], fill=cols[i % len(cols)], width=1)
    for i, p in enumerate(points):
        r, c = project(K, E, p)[0]
        dr.ellipse([c - 3, r - 3, c + 3, r + 3], outline=cols[i % len(cols)], width=2)
    for i, (a, b) in enumerate(lines):
        (r0, c0), (r1, c1) = project(K, E, [a, b])
        dr.line([(c0, r0), (c1, r1)], fill=cols[i % len(cols)], width=2)
    return im.resize((im.width * scale, im.height * scale))


def lid_top_edge(robo):
    """Top edge of the open lid from the head-view screen mask and the height prior."""
    s = segment(robo, SCREEN_PROMPT)
    if s is None:
        return dict(ok=False, reason='screen mask not found')
    K, E = cam(robo)
    rows, cols = np.nonzero(s['mask'])
    c0, c1 = np.percentile(cols, [4, 96])
    top = []
    for c in np.unique(cols):
        if c0 <= c <= c1:
            top.append((rows[cols == c].min(), c))
    top = np.asarray(top, float)
    slope, icpt = np.polyfit(top[:, 1], top[:, 0], 1)
    cl, cr = cols.min(), cols.max()
    tl = ray_at_z(K, E, (slope * cl + icpt, cl), LID_TOP_Z)
    tr = ray_at_z(K, E, (slope * cr + icpt, cr), LID_TOP_Z)
    width = float(np.linalg.norm(tr - tl))
    axis = (tr - tl) / width
    closing = np.cross(axis, [0, 0, 1.0])
    if closing[1] > 0:
        closing = -closing
    return dict(ok=0.15 < width < 0.21, tl=tl, tr=tr, top_center=(tl + tr) / 2, width=width,
                axis=axis, closing=closing / np.linalg.norm(closing),
                yaw_deg=math.degrees(math.atan2(axis[1], axis[0])), score=s['score'], mask=s)


def _rx(a):
    c, s = math.cos(a), math.sin(a)
    return np.array([[1.0, 0.0, 0.0], [0.0, c, -s], [0.0, s, c]])


def _ry(a):
    c, s = math.cos(a), math.sin(a)
    return np.array([[c, 0.0, s], [0.0, 1.0, 0.0], [-s, 0.0, c]])


def _rz(a):
    c, s = math.cos(a), math.sin(a)
    return np.array([[c, -s, 0.0], [s, c, 0.0], [0.0, 0.0, 1.0]])


def orientation(pitch, yaw, roll):
    """Gripper rotation for (pitch, yaw, roll) in degrees: Rz(90 + yaw) Ry(pitch) Rx(roll)."""
    return _rz(math.radians(90.0 + yaw)) @ _ry(math.radians(pitch)) @ _rx(math.radians(roll))


def angles(rot):
    """(pitch, yaw, roll) in degrees of a gripper rotation (not within a degree of vertical)."""
    point = rot[:, 0]
    pitch = math.degrees(math.asin(max(-1.0, min(1.0, -point[2]))))
    yaw = math.degrees(math.atan2(point[1], point[0])) - 90.0
    rest = orientation(pitch, yaw, 0.0).T @ rot
    roll = math.degrees(math.atan2(rest[2, 1], rest[1, 1]))
    wrap = lambda d: (d + 180.0) % 360.0 - 180.0
    return pitch, wrap(yaw), wrap(roll)


LOG = []


def used(robo):
    return int(robo.action_count())


def go(robo, arm, xyz, pitch=None, yaw=None, roll=None, path='line', gripper=0, label=''):
    """One move with a compact reply appended to LOG."""
    before = used(robo)
    m = robo.move_to([float(v) for v in xyz], arm=arm, gripper=gripper, pitch=pitch, yaw=yaw, roll=roll, path=path)
    rec = dict(label=label, arm=arm, reached=bool(m.reached), blocked=bool(getattr(m, 'blocked', False)),
               dist=float(getattr(m, 'dist_to_target_m', float('nan'))), note=getattr(m, 'note', None),
               ik_error=getattr(m, 'ik_error', None), actions=used(robo) - before, at=used(robo))
    LOG.append(rec)
    return rec


def approach(robo, arm, xyz, opening=None, label='', **kw):
    """Move an EMPTY hand to a pose with its fingers closed, then open it.

    With an open empty gripper the arm may take the pose turned half a turn
    about its pointing direction, which swaps the fingers and puts the wrist
    camera on the other side. A closed hand is taken exactly as asked.
    ``opening`` None leaves the hand closed; 1.0 opens fully.
    """
    rec = go(robo, arm, xyz, gripper=robo.CLOSE, label=label, **kw)
    if opening is not None and rec['reached']:
        before = used(robo)
        if opening >= 1.0:
            robo.set_gripper(arm, robo.OPEN)
        else:
            robo.set_gripper(arm, robo.OPEN, opening=opening)
        rec = dict(rec, actions=rec['actions'] + used(robo) - before, opened=opening)
    return rec


def glide(robo, arm, xyz, step_m=0.015, label='', **kw):
    """Straight move in short steps, one action each: no swing, low acceleration."""
    start = np.asarray(robo.state().arm(arm).tcp_pos, float)
    goal = np.asarray(xyz, float)
    n = max(1, int(math.ceil(np.linalg.norm(goal - start) / step_m)))
    before = used(robo)
    rec = None
    for k in range(1, n + 1):
        rec = go(robo, arm, start + (goal - start) * k / n, path='line', label=label, **kw)
        if not rec['reached'] and rec.get('ik_error'):
            break
    rec = dict(rec, actions=used(robo) - before, steps=n)
    return rec


def sheet(images, cols=4, size=(320, 240)):
    """Contact sheet of PIL/array images."""
    ims = [Image.fromarray(np.asarray(i)).convert('RGB').resize(size) for i in images]
    rows = (len(ims) + cols - 1) // cols
    out = Image.new('RGB', (cols * size[0], rows * size[1]))
    for i, im in enumerate(ims):
        out.paste(im, ((i % cols) * size[0], (i // cols) * size[1]))
    return out
# Hinge relative to the open lid top edge. docs/store_laptop_and_headphones/applied_values.json
HINGE_LOCAL = (-0.001, 0.039, -0.114)
LAPTOP_PROMPTS = ('laptop', 'closed silver laptop', 'silver laptop computer')


def lid_closed(robo, L, tol_px=10):
    """Closed when the laptop mask no longer rises above the projected hinge line."""
    s = None
    for prompt in LAPTOP_PROMPTS:
        s = segment(robo, prompt)
        if s is not None:
            break
    if s is None:
        return dict(closed=None, reason='laptop mask not found')
    K, E = cam(robo)
    basis = np.column_stack([L['axis'], L['closing'], [0, 0, 1.0]])
    hinge = L['top_center'] + basis @ np.asarray(HINGE_LOCAL)
    hinge_row = float(project(K, E, hinge)[0][0])
    top_row = float(np.percentile(np.nonzero(s['mask'])[0], 2))
    return dict(closed=bool(top_row > hinge_row - tol_px), top_row=top_row, hinge_row=hinge_row, score=s['score'])


LID_BRACE = True


def _measured_step():
    """One quarter of the measured laptop depth."""
    return float(LAPTOP_DIMS[1]) / 4.0


def brace_base(robo, L, arm='left'):
    """Other hand, closed, presses the keyboard deck at the measured front edge.

    Returns the pressed place; ``release_brace`` lifts the hand again.
    """
    basis = np.column_stack([L['axis'], L['closing'], [0.0, 0.0, 1.0]])
    hinge = np.asarray(L['top_center'], float) + basis @ np.asarray(HINGE_LOCAL)
    p = hinge + np.asarray(L['closing'], float) * float(LAPTOP_DIMS[1])
    p[2] = float(hinge[2])
    z_lo = float(p[2])
    z_hi = z_lo + _measured_step()
    pitch = float(robo.state().arm(arm).pitch)
    yaw = float(L['yaw_deg'])
    fine = True
    for z in (z_hi, z_lo):
        pv = robo.preview_move([float(p[0]), float(p[1]), z], arm=arm, path='auto', pitch=pitch, yaw=yaw, roll=0)
        fine = fine and bool(pv.get('reachable')) and not pv.get('ik_error')
    plan = pitch if fine else None
    if plan is None:
        return dict(ok=False, reason='deck corner not within reach of the other arm', replies=[])
    recs = [go(robo, arm, [p[0], p[1], z_hi], pitch=plan, yaw=yaw, roll=0, path='auto', gripper=robo.CLOSE, label='brace-near')]
    if not recs[-1]['reached']:
        return dict(ok=False, reason='pose above the deck not reached', replies=recs)
    z, touched = z_hi, False
    while z > z_lo + 1e-6:
        z -= _measured_step()
        r = go(robo, arm, [p[0], p[1], z], pitch=plan, yaw=yaw, roll=0, gripper=robo.CLOSE, label='brace-down')
        if r['blocked'] or not r['reached']:
            touched = True
            break
    at = np.asarray(robo.state().arm(arm).tcp_pos, float)
    touched = touched or bool(at[2] > z + 0.002)
    recs.append(dict(label='brace-down', touched=touched, z=round(float(at[2]), 4), at=used(robo)))
    return dict(ok=True, touched=touched, point=p, pitch=plan, yaw=yaw, replies=recs)


def release_brace(robo, B, arm='left'):
    """Lift the bracing hand straight up and send that arm home (out of the head view and of the lid's way)."""
    at = np.asarray(robo.state().arm(arm).tcp_pos, float)
    a = math.radians(B['yaw'])
    back = -np.array([-math.sin(a), math.cos(a)])
    step = _measured_step()
    recs = []
    recs.append(go(robo, arm, [at[0] + back[0] * step, at[1] + back[1] * step, at[2] + step], pitch=B['pitch'], yaw=B['yaw'], roll=0, gripper=robo.CLOSE, label='brace-back'))
    h = robo.home(arm)
    recs.append(dict(label='brace-home', reached=bool(getattr(h, 'reached', False)), actions=int(getattr(h, 'steps_used', 0)), at=used(robo)))
    return recs


def close_lid(robo, L, arm='right', frames=None):
    """Push the open lid shut along the reference arc. L is lid_top_edge().

    The approach to precontact is one move. From there the pusher advances in
    small steps, one action each. A blocked step is normal lid
    resistance and is not repeated. Closure is measured afterwards.
    """
    yaw = L['yaw_deg']
    pitch = float(robo.state().arm(arm).pitch)
    start = used(robo)
    out = []
    labels = ['precontact', 'close']
    pts = [np.asarray(L['top_center'], float), np.asarray(L['top_center'], float) + np.asarray(L['closing'], float) * float(LAPTOP_DIMS[1])]
    rec = approach(robo, arm, pts[0], opening=1.0, pitch=pitch, yaw=yaw, roll=0.0, path='auto', label='precontact')
    out.append(rec)
    if frames is not None:
        frames.append(robo.image('cam_head'))
    if not rec['reached']:
        return dict(ok=False, reason='precontact not reached', replies=out, actions=used(robo) - start)
    brace = None
    if LID_BRACE:
        brace = brace_base(robo, L, arm='left' if arm == 'right' else 'right')
        out.extend(brace['replies'])
        out.append(dict(label='brace', ok=brace['ok'], reason=brace.get('reason'), touched=brace.get('touched'), at=used(robo)))
        if frames is not None:
            frames.append(robo.image('cam_head'))
    for i in range(1, len(pts)):
        held = i == 1 and brace is not None and brace['ok'] and brace.get('touched')
        n = max(1, int(math.ceil(np.linalg.norm(pts[i] - pts[i - 1]) / _measured_step())))
        for relief in (0, 1):
            blocked = 0
            for k in range(1, n + 1):
                r = go(robo, arm, pts[i - 1] + (pts[i] - pts[i - 1]) * k / n, pitch=pitch, yaw=yaw, roll=0.0, label=labels[i])
                blocked += int(r['blocked'])
            out.append(dict(label=labels[i], steps=n, blocked=blocked, at=used(robo), relief=relief))
            if i < 2 or n < 4 or blocked < n or relief:
                break
            s_now = robo.state().arm(arm)
            out.append(go(robo, arm, np.asarray(s_now.tcp_pos) + [0, 0, _measured_step()], pitch=pitch, yaw=yaw, roll=0.0, label='lid-relief'))
            out.append(go(robo, arm, pts[i - 1] + np.array([0, 0, _measured_step()]), pitch=pitch, yaw=yaw, roll=0.0, label='lid-return'))
        if i == 1 and brace is not None and brace['ok']:
            out.extend(release_brace(robo, brace, arm='left' if arm == 'right' else 'right'))
        if frames is not None:
            frames.append(robo.image('cam_head'))
    s = robo.state().arm(arm)
    out.append(go(robo, arm, np.asarray(s.tcp_pos) + [0, 0, _measured_step()], pitch=pitch, yaw=yaw, roll=0.0, label='lid-withdraw'))
    check = lid_closed(robo, L)
    return dict(ok=bool(check.get('closed')), check=check, replies=out, actions=used(robo) - start)


def min_area_rect(points):
    """Minimum-area rectangle of 2D points: centre, (long, short), long-axis angle (rad), corners."""
    pts = np.asarray(points, float)
    P = sorted(map(tuple, np.unique(np.round(pts, 5), axis=0)))
    def half(seq):
        h = []
        for p in seq:
            while len(h) >= 2 and ((h[-1][0]-h[-2][0])*(p[1]-h[-2][1]) - (h[-1][1]-h[-2][1])*(p[0]-h[-2][0])) <= 0:
                h.pop()
            h.append(p)
        return h[:-1]
    hull = np.asarray(half(P) + half(P[::-1]))
    best = None
    for i in range(len(hull)):
        e = hull[(i + 1) % len(hull)] - hull[i]
        n = np.linalg.norm(e)
        if n < 1e-9:
            continue
        u = e / n
        v = np.array([-u[1], u[0]])
        a, b = hull @ u, hull @ v
        area = (a.max() - a.min()) * (b.max() - b.min())
        if best is None or area < best[0]:
            best = (area, u, v, a.min(), a.max(), b.min(), b.max())
    _, u, v, a0, a1, b0, b1 = best
    centre = u * (a0 + a1) / 2 + v * (b0 + b1) / 2
    la, lb = a1 - a0, b1 - b0
    corners = np.array([u*a0+v*b0, u*a1+v*b0, u*a1+v*b1, u*a0+v*b1])
    if la >= lb:
        long_dir, dims = u, (la, lb)
    else:
        long_dir, dims = v, (lb, la)
    ang = math.atan2(long_dir[1], long_dir[0])
    ang = (ang + math.pi / 2) % math.pi - math.pi / 2
    return dict(centre=centre, dims=dims, angle=ang, corners=corners)


def mask_outline_at_z(robo, m, z, camera='cam_head', step=2):
    """World XY of a mask's outline pixels intersected with the plane at height z."""
    K, E = cam(robo, camera)
    pts = []
    for outline in m['seg'].contours_rc or ():
        for r, c in outline[::step]:
            pts.append(ray_at_z(K, E, (r, c), z)[:2])
    return np.asarray(pts)


# docs/store_laptop_and_headphones/geometry_fit.json, laptop_closure_geometry.
LAPTOP_DIMS = (0.179, 0.126)


def closed_laptop_pose(robo, top_z=None, toward=None):
    """Planar pose of the CLOSED laptop from its head-view mask at the top-face height.

    Returns the rectangle centre, the width axis x_dir, the depth axis y_dir
    (front edge → hinge edge) and both edge centres. The hinge side is the far
    side from the robot unless ``toward`` (a world XY direction from the front
    edge to the hinge edge, e.g. the donor gripper's heading) is given.
    """
    s = None
    for prompt in LAPTOP_PROMPTS:
        s = segment(robo, prompt)
        if s is not None:
            break
    if s is None:
        return dict(ok=False, reason='laptop mask not found')
    xy = mask_outline_at_z(robo, s, top_z)
    r = min_area_rect(xy)
    long_dir = np.array([math.cos(r['angle']), math.sin(r['angle'])])
    short_dir = np.array([-long_dir[1], long_dir[0]])
    ref = np.array([0.0, 1.0]) if toward is None else np.asarray(toward, float)[:2]
    y_dir = short_dir if short_dir @ ref >= 0 else -short_dir
    x_dir = np.array([y_dir[1], -y_dir[0]])
    hinge = r['centre'] + y_dir * r['dims'][1] / 2
    front = hinge - y_dir * LAPTOP_DIMS[1]
    ok = abs(r['dims'][0] - LAPTOP_DIMS[0]) < 0.03 and abs(r['dims'][1] - LAPTOP_DIMS[1]) < 0.04
    return dict(ok=bool(ok), centre=np.array([r['centre'][0], r['centre'][1], top_z]), dims=r['dims'],
                x_dir=np.r_[x_dir, 0.0], y_dir=np.r_[y_dir, 0.0], front=np.r_[front, top_z], hinge=np.r_[hinge, top_z],
                yaw_deg=math.degrees(math.atan2(x_dir[1], x_dir[0])), corners=r['corners'], score=s['score'], mask=s)
CUP_MID_Z = TABLE_Z


def headset_cups(robo, min_sep_m=0.07, max_sep_m=0.19):
    """Earcup centres of the headset lying on the table, from the head-view mask.

    The two earcups are the thick lobes of the mask; the band is thin. The lobes
    are the two strongest, well separated maxima of the mask's distance
    transform. They are placed in the world at the earcup mid-height prior.
    Returns cups ordered left→right (world x), their axis and the band side.
    """
    import cv2
    s = segment(robo, HEADSET_PROMPT)
    if s is None:
        return dict(ok=False, reason='headset mask not found')
    K, E = cam(robo)
    m = s['mask'].astype(np.uint8)
    dt = cv2.distanceTransform(m, cv2.DIST_L2, 5)
    peaks = []
    work = dt.copy()
    for _ in range(4):
        r, c = np.unravel_index(np.argmax(work), work.shape)
        v = float(work[r, c])
        if v < 3:
            break
        peaks.append((r, c, v))
        cv2.circle(work, (int(c), int(r)), int(max(1.6 * v, 8)), 0, -1)
    best = None
    for i in range(len(peaks)):
        for j in range(i + 1, len(peaks)):
            a = ray_at_z(K, E, peaks[i][:2], CUP_MID_Z)
            b = ray_at_z(K, E, peaks[j][:2], CUP_MID_Z)
            sep = float(np.linalg.norm(a - b))
            if min_sep_m <= sep <= max_sep_m:
                score = peaks[i][2] + peaks[j][2]
                if best is None or score > best[0]:
                    best = (score, a, b, peaks[i], peaks[j], sep)
    if best is None:
        return dict(ok=False, reason='two earcup lobes not found', peaks=peaks, mask=s)
    _, a, b, pa, pb, sep = best
    if a[0] > b[0]:
        a, b, pa, pb = b, a, pb, pa
    axis = (b - a) / np.linalg.norm(b - a)
    mid = (a + b) / 2
    rows, cols = np.nonzero(m)
    sel = np.arange(0, len(rows), max(1, len(rows) // 1500))
    pts = np.array([ray_at_z(K, E, (rows[k], cols[k]), STAND_BASE_Z) for k in sel])
    across = np.cross([0, 0, 1.0], axis)
    t = (pts - mid) @ across
    band_dir = across if np.mean(t) > 0 else -across
    thin = dt[rows[sel], cols[sel]] < 0.5 * min(pa[2], pb[2])
    band_reach = float(np.percentile(np.abs((pts[thin] - mid) @ across), 90)) if thin.any() else None
    return dict(ok=True, left=a, right=b, mid=mid, axis=axis, band_dir=band_dir, sep=sep,
                yaw_deg=math.degrees(math.atan2(axis[1], axis[0])), band_reach=band_reach,
                peaks_rc=[pa[:2], pb[:2]], lobe_px=[pa[2], pb[2]], score=s['score'], mask=s)


def headset_cups_clear(robo):
    """``headset_cups`` with the parked left hand moved out of the way when it hides the headset.

    The left hand parks 13 cm above the table, between the head camera and the near left part of the table. A
    headset lying there shows only one clean earcup: the lobes can then be found
    15 cm apart instead of 8 (grasps close on nothing), or no two lobes are found at all and
    the stage cannot start. With the hand pulled back and up the same view gives both earcups (lobes 18 and 20 px
    against 6 and 8). The hand is moved only when the first measurement fails or puts an earcup next to the hand.
    """
    H = headset_cups(robo)
    tcp = np.asarray(robo.state().arm('left').tcp_pos, float)
    hide = float(min(CRADLE_DIMS)) / 2.0
    if H.get('ok') and min(float(np.linalg.norm(np.asarray(H[k][:2], float) - tcp[:2])) for k in ('left', 'right')) >= hide:
        return H
    rec = dict(label='left-home', reached=bool(getattr(robo.home('left'), 'reached', False)))
    H2 = headset_cups(robo)
    if H2.get('ok') or not H.get('ok'):
        return dict(H2, hand_moved_aside=True, aside_reply=rec, first_ok=bool(H.get('ok')))
    return dict(H, hand_moved_aside=True, aside_reply=rec, second_reason=H2.get('reason'))


def cup_closeup(robo, guess, arm='left', which='left', prior_yaw=None):
    """Earcup centre and long axis from the wrist camera at the arm's current orientation.

    The camera is placed above the head-view estimate ``guess`` at the height
    between the measured table and the measured cradle. Table-coloured pixels
    inside the mask are removed. When the cup is cut by the image border the
    camera is shifted onto the measured centre and the cup is measured again.
    """
    import cv2
    start = used(robo)
    z = STAND_BASE_Z
    name = 'cam_%s_wrist' % arm

    def look(ref):
        s = segment(robo, HEADSET_PROMPT, name)
        if s is None:
            return dict(ok=False, reason='headset not seen by the wrist camera')
        K, E = cam(robo, name)
        rgb = np.ascontiguousarray(np.asarray(robo.image(name))[:, :, :3])
        f = mask_of(s['seg']).astype(np.uint8)
        ring = (cv2.dilate(f, np.ones((21, 21), np.uint8)) > 0) & ~(cv2.dilate(f, np.ones((7, 7), np.uint8)) > 0)
        lab = cv2.cvtColor(rgb, cv2.COLOR_RGB2LAB).astype(np.float32)
        m = f.copy()
        if ring.sum() > 200:
            mu, sd = lab[ring].mean(axis=0), lab[ring].std(axis=0) + 4.0
            d = np.sqrt((((lab - mu) / sd) ** 2).sum(axis=2))
            m[(d < 2.5)] = 0
            m = cv2.morphologyEx(m, cv2.MORPH_OPEN, np.ones((5, 5), np.uint8))
        dt = cv2.distanceTransform(m, cv2.DIST_L2, 5)
        lobes = []
        work = dt.copy()
        for _ in range(3):
            r, c = np.unravel_index(np.argmax(work), work.shape)
            v = float(work[r, c])
            if v < 10:
                break
            core = (dt > 0.45 * v).astype(np.uint8)
            n, lab_i = cv2.connectedComponents(core)
            rr, cc = np.nonzero(lab_i == lab_i[r, c])
            sel = np.arange(0, len(rr), max(1, len(rr) // 600))
            pts = np.array([ray_at_z(K, E, (rr[k], cc[k]), z)[:2] for k in sel])
            mean = pts.mean(axis=0)
            w, vec = np.linalg.eigh(np.cov((pts - mean).T))
            long_dir = vec[:, 1] if vec[1, 1] >= 0 else -vec[:, 1]
            edge = bool(rr.min() <= 2 or cc.min() <= 2 or rr.max() >= dt.shape[0] - 3 or cc.max() >= dt.shape[1] - 3)
            lobes.append(dict(centre=mean, long_dir=long_dir, elong=float(np.sqrt(w[1] / max(w[0], 1e-9))), px=v, cut=edge))
            work[lab_i == lab_i[r, c]] = 0
            cv2.circle(work, (int(c), int(r)), int(1.5 * v), 0, -1)
        top = max([l['px'] for l in lobes], default=0.0)
        lobes = [l for l in lobes if l['elong'] > 1.25 and l['px'] >= 0.5 * top]
        if len(lobes) < 1:
            return dict(ok=False, reason='no earcup slab found in the wrist view', mask=s)
        lobe = min(lobes, key=lambda l: float(np.linalg.norm(l['centre'] - np.asarray(ref)[:2])))
        view = ray_at_z(K, E, (K[1, 2], K[0, 2]), z)[:2]
        return dict(ok=True, lobe=lobe, lobes=len(lobes), off_view=np.asarray(lobe['centre']) - np.asarray(view), mask=s)

    look_z = _carry_z()
    st = robo.state().arm(arm)
    rec = approach(robo, arm, [guess[0], guess[1], look_z], pitch=float(st.pitch), yaw=float(st.yaw), roll=float(st.roll), path='auto', label='cup-look')
    m = look(guess)
    looks = 1
    if m.get('ok') and (float(np.linalg.norm(m['off_view'])) > 0.025 or m['lobe']['cut']):
        at = np.asarray(robo.state().arm(arm).tcp_pos, float)
        span = float(min(CRADLE_DIMS))
        shift = np.clip(m['off_view'], -span, span)
        st = robo.state().arm(arm)
        rec2 = go(robo, arm, [at[0] + shift[0], at[1] + shift[1], look_z], pitch=float(st.pitch), yaw=float(st.yaw), roll=float(st.roll), path='auto', gripper=robo.CLOSE, label='cup-look-centred')
        if rec2['reached']:
            m2 = look(m['lobe']['centre'])
            looks = 2
            if m2.get('ok') and float(np.linalg.norm(np.asarray(m2['lobe']['centre']) - np.asarray(m['lobe']['centre']))) < 0.05:
                m = m2
    if not m.get('ok'):
        return dict(ok=False, reason=m.get('reason'), reply=rec, actions=used(robo) - start, mask=m.get('mask'))
    lobe = m['lobe']
    free_end = lobe['centre']
    fin = np.array([lobe['long_dir'][1], -lobe['long_dir'][0]])
    yaw_g = math.degrees(math.atan2(fin[1], fin[0]))
    yaw_g = (yaw_g + 90.0) % 180.0 - 90.0
    yaw_trusted = True
    if prior_yaw is not None:
        diff = (yaw_g - prior_yaw + 90.0) % 180.0 - 90.0
        if abs(diff) > 20.0:
            yaw_g, yaw_trusted = float(prior_yaw), False
    near = float(np.linalg.norm(lobe['centre'] - np.asarray(guess)[:2]))
    return dict(ok=bool(near < 0.06 and free_end is not None), centre=np.array([lobe['centre'][0], lobe['centre'][1], z]), long_dir=lobe['long_dir'],
                free_end=free_end,
                finger_yaw_deg=yaw_g, yaw_trusted=yaw_trusted, elong=lobe['elong'], lobes=m['lobes'], moved_from_guess=near, reply=rec,
                looks=looks, off_view_m=float(np.linalg.norm(m['off_view'])), actions=used(robo) - start, mask=m['mask'])


# Stand frame origin: the fitted table height.
STAND_Z = TABLE_Z
# Geometry fit. docs/store_laptop_and_headphones/geometry_fit.json
CRADLE_OUTLINE_Z = 1.0272
# RGB-derived: three-seed median (geometry); docs/store_laptop_and_headphones/applied_values.json (rgb_derived_values).
CRADLE_DIMS = (0.181, 0.099)
STAND_BASE_Z = 0.787  # RGB-derived median; uncertainty in docs/store_laptop_and_headphones/applied_values.json.


def stand_pose(robo):
    """Headphone stand centre and long-axis yaw from the head view.

    The mask's thick parts are the cradle (top) and the base plate (on the
    table); the thin pole is removed by a morphological opening. The base plate
    is a flat rectangle, so its outline on the table plane gives the yaw and
    centre; the cradle blob placed at the cradle-height prior cross-checks the
    centre.
    """
    first = None
    for prompt in STAND_PROMPTS:
        r = _stand_pose_from(robo, prompt)
        if r.get('ok'):
            return dict(r, prompt=prompt)
        first = first or r
    for prompt in STAND_PROMPTS + STAND_BASE_PROMPTS:
        r = _stand_pose_from(robo, prompt, base_only=True)
        if r.get('ok'):
            return dict(r, prompt=prompt)
    return first


STAND_BASE_PROMPTS = ('rectangular wooden base plate', 'brown wooden board on the table')
STAND_BASE_DIMS = CRADLE_DIMS


def _stand_pose_from(robo, prompt, base_only=False):
    import cv2
    s = segment(robo, prompt)
    if s is None:
        return dict(ok=False, reason='stand mask not found')
    K, E = cam(robo)
    m = s['mask'].astype(np.uint8)
    dt = cv2.distanceTransform(m, cv2.DIST_L2, 5)
    size = int(1.3 * float(dt.max())) | 1
    k = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (size, size))
    blob = cv2.morphologyEx(m, cv2.MORPH_OPEN, k)
    n, lab, stats, cent = cv2.connectedComponentsWithStats(blob)
    parts = sorted([(cent[i][1], i) for i in range(1, n) if stats[i, cv2.CC_STAT_AREA] > 300])

    def outline_xy(i, z):
        cs, _ = cv2.findContours((lab == i).astype(np.uint8), cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_NONE)
        o = max(cs, key=len)[:, 0, :]
        return np.array([ray_at_z(K, E, (r, c), z)[:2] for c, r in o[::2]])

    if base_only:
        cands = [i for _, i in parts]
        best = None
        for i in cands:
            r = min_area_rect(outline_xy(i, STAND_BASE_Z))
            yaw = math.degrees(r['angle'])
            fit = abs(r['dims'][0] - STAND_BASE_DIMS[0]) + abs(r['dims'][1] - STAND_BASE_DIMS[1])
            if (abs(r['dims'][0] - STAND_BASE_DIMS[0]) < 0.025 and abs(r['dims'][1] - STAND_BASE_DIMS[1]) < 0.02
                    and (best is None or fit < best[0])):
                best = (fit, r, yaw)
        if best is None:
            return dict(ok=False, reason='no base-plate-shaped blob', parts=len(parts), mask=s)
        _, base, yaw = best
        a = base['angle']
        R = np.array([[math.cos(a), -math.sin(a), 0], [math.sin(a), math.cos(a), 0], [0, 0, 1.0]])
        return dict(ok=True, centre=np.array([base['centre'][0], base['centre'][1], STAND_Z]), yaw_deg=yaw, R=R,
                    dims=base['dims'], corners=base['corners'], cradle_xy=None, gap=None, base_only=True, score=s['score'], mask=s)
    if len(parts) < 2:
        return dict(ok=False, reason='cradle and base blobs not both found', parts=len(parts), mask=s)

    cradle_xy = outline_xy(parts[0][1], CRADLE_OUTLINE_Z).mean(axis=0)
    base = min_area_rect(outline_xy(parts[-1][1], STAND_BASE_Z))
    yaw = math.degrees(base['angle'])
    gap = float(np.linalg.norm(cradle_xy - base['centre']))
    ok = abs(base['dims'][0] - CRADLE_DIMS[0]) < 0.04 and gap < 0.03
    a = base['angle']
    R = np.array([[math.cos(a), -math.sin(a), 0], [math.sin(a), math.cos(a), 0], [0, 0, 1.0]])
    return dict(ok=bool(ok), centre=np.array([base['centre'][0], base['centre'][1], STAND_Z]), yaw_deg=yaw, R=R,
                dims=base['dims'], corners=base['corners'], cradle_xy=cradle_xy, gap=gap, score=s['score'], mask=s)


CUP_GRASP_Z = TABLE_Z
HANG_GRASP_Z = TABLE_Z


def band_apex(robo, apex_z):
    """Top of the held headband from one head view, in free space.

    The apex is the highest part of the headset mask; its ray is intersected
    with the horizontal plane at the apex height, which is known to a few
    millimetres while held upright (a tilt in the grip barely changes it).
    """
    s = segment(robo, HEADSET_PROMPT)
    if s is None:
        return dict(ok=False, reason='headset mask not found')
    K, E = cam(robo)
    rows, cols = np.nonzero(s['mask'])
    top = rows.min()
    sel = rows <= top + 3
    apex = ray_at_z(K, E, (float(rows[sel].mean()), float(cols[sel].mean())), apex_z)
    return dict(ok=True, apex=apex, score=s['score'], top_row=int(top))


def hung_offset(robo, St, stand_mask):
    """How far the hanging earcups sit, in head-image pixels, from where a correctly hung headset's would.

    Once the headset hangs on the stand its mask merges with the cradle, so the
    stand's earlier silhouette is removed; what is left is mostly the two
    earcups below the cradle. Their centroid is compared with the projection of
    the earcup centres of an ideally hung headset. A
    correct hang was within about 10 px and every tipped, slipped or fallen
    headset was 25 px or more away.
    """
    import cv2
    s = segment(robo, HEADSET_PROMPT)
    if s is None:
        return dict(ok=False, reason='headset mask not found')
    K, E = cam(robo)
    m = s['mask'] & ~(cv2.dilate(stand_mask.astype(np.uint8), np.ones((5, 5), np.uint8)) > 0)
    rows, cols = np.nonzero(m)
    if len(rows) < 400:
        return dict(ok=False, reason='too little of the headset visible beside the stand', pixels=int(len(rows)))
    centre = np.asarray(St['centre'])
    R = np.asarray(St['R'])
    span = float(min(CRADLE_DIMS)) / 2.0
    cups = [centre + R @ np.array([sx * span, 0.0, 0.0]) for sx in (-1.0, 1.0)]
    want = project(K, E, cups).mean(axis=0)
    got = np.array([rows.mean(), cols.mean()])
    return dict(ok=True, offset_px=float(np.linalg.norm(got - want)), d_row=float(got[0] - want[0]), d_col=float(got[1] - want[1]),
                pixels=int(len(rows)), score=s['score'])
def _side_look_pose(robo, St, holder, observer, sign):
    """Observer pose beside the held headset, from the hand and the measured stand."""
    holder_tcp = np.asarray(robo.state().arm(holder).tcp_pos, float)
    lateral = np.asarray(St['R'], float)[:, 0]
    lateral = lateral / max(float(np.linalg.norm(lateral[:2])), 1e-6)
    stand = np.asarray(St['centre'], float)
    gap = float(np.linalg.norm(holder_tcp[:2] - stand[:2]))
    look = holder_tcp + sign * lateral * gap
    look[2] = float(holder_tcp[2])
    toward = holder_tcp[:2] - look[:2]
    yaw = math.degrees(math.atan2(float(toward[1]), float(toward[0]))) - 90.0
    pitch = float(robo.state().arm(observer).pitch)
    return look, pitch, yaw


def side_mask(robo, name, holder):
    """Headset mask in the observer's side view, with further tries when the usual prompt finds nothing.

    The held headset fills a third of this close view and its lower part is hidden behind the observer's own
    fingers; the usual prompt can return nothing although the headset is in
    plain view. Other wordings and a lower score are then tried; such a mask is only accepted when it is large
    and lies at the pinch (the holder's fingertips projected into the picture), so that no other object is taken.
    """
    s = segment(robo, HEADSET_PROMPT, name)
    if s is not None:
        return s, 'headphones/0.20'
    K, E = cam(robo, name)
    pr, pc = project(K, E, [np.asarray(robo.state().arm(holder).tcp_pos, float)])[0]
    for prompt in ('headset', 'headphones', 'over-ear headphones'):
        s = segment(robo, prompt, name)
        if s is None:
            continue
        rows, cols = np.nonzero(s['mask'])
        if len(rows) and rows.min() - 90 <= pr <= rows.max() + 90 and cols.min() - 90 <= pc <= cols.max() + 90:
            return s, prompt
    return None, None


def side_look(robo, St, holder='left', observer='right'):
    """Where the held headset's band apex is relative to the pinch, from a calibrated side view.

    The observer arm's wrist camera looks across the table at the upright
    headset held by the other arm. The top of the headset mask is the band
    apex; its ray is intersected with the headset's symmetry plane, which the
    view crosses almost square-on. That gives how far ahead of the pinch the
    band is (decides where it lands on the cradle) and how high above the pinch
    it is (decides the approach height through the gap between cradle and earcups).
    """
    start = used(robo)
    look, pitch, yaw = _side_look_pose(robo, St, holder, observer, 1.0)
    rec = approach(robo, observer, look, pitch=pitch, yaw=yaw, roll=0.0, path='auto', label='side-look')
    if not rec['reached']:
        return dict(ok=False, reason='observer pose not reached', reply=rec, actions=used(robo) - start)
    name = 'cam_%s_wrist' % observer
    s, how = side_mask(robo, name, holder)
    if s is None:
        look2, pitch2, yaw2 = _side_look_pose(robo, St, holder, observer, -1.0)
        rec2 = approach(robo, observer, look2, pitch=pitch2, yaw=yaw2, roll=0.0, path='auto', label='side-look-back')
        if rec2['reached']:
            s, how = side_mask(robo, name, holder)
            how = None if how is None else how + ' from the second pose'
    if s is None:
        return dict(ok=False, reason='headset not seen from the side', reply=rec, actions=used(robo) - start)
    K, E = cam(robo, name)
    R = np.asarray(St['R'])
    tcp = np.asarray(robo.state().arm(holder).tcp_pos)
    n = R[:, 0]
    p0 = tcp + 0 * n
    rows, cols = np.nonzero(s['mask'])
    top = rows.min()
    sel = rows <= top + 2
    o, d = pixel_ray(K, E, (float(top), float(np.median(cols[sel]))))
    denom = float(d @ n)
    if abs(denom) < 0.5:
        return dict(ok=False, reason='side view not square to the headset', reply=rec, actions=used(robo) - start)
    apex = o + (float((p0 - o) @ n) / denom) * d
    ahead = float((apex - tcp) @ R[:, 1])
    up = float(apex[2] - tcp[2])
    span = float(max(CRADLE_DIMS))
    ok = bool(float(min(CRADLE_DIMS)) / 2.0 <= up <= span and abs(ahead) <= span and top > 2)
    return dict(ok=ok, apex=apex, ahead=ahead, apex_up=up, centre_up=up / 2.0, top_row=int(top),
                score=s['score'], found_by=how, reply=rec, actions=used(robo) - start, mask=s)


def side_check(robo, St, observer='right'):
    """Postcondition of the hang, from the observer arm's side view.

    The top of the headset mask (which merges with the cradle once it hangs
    there) is intersected with the stand's mid-plane. A band resting on the
    cradle puts that top at least a centimetre above the bare cradle top and
    over the cradle's depth; a headset that slipped, tipped or fell does not.
    """
    name = 'cam_%s_wrist' % observer
    s = segment(robo, HEADSET_PROMPT, name)
    if s is None:
        return dict(ok=False, seated=False, reason='headset not seen from the side')
    K, E = cam(robo, name)
    R = np.asarray(St['R'])
    centre = np.asarray(St['centre'])
    n = R[:, 0]
    rows, cols = np.nonzero(s['mask'])
    top = rows.min()
    sel = rows <= top + 2
    o, d = pixel_ray(K, E, (float(top), float(np.median(cols[sel]))))
    denom = float(d @ n)
    if abs(denom) < 0.3:
        return dict(ok=False, seated=False, reason='side view not square to the stand')
    local = R.T @ (o + (float((centre - o) @ n) / denom) * d - centre)
    seated = bool(top > 2)
    return dict(ok=True, seated=seated, band_top_in_stand=local, top_row=int(top), score=s['score'])



def held_band_look(robo, St, holder='left', observer='right'):
    """Where the top of the held headset's band is over the stand, from the observer arm's side view.

    Same construction as the side look, without moving the observer: the top
    of the headset mask is intersected with the headset's own symmetry plane
    (through the pinch) and expressed in the stand frame. The headset's
    earcups nearly touch each other, so they cannot pass the stand's post:
    a hand that advances a centimetre too far presses them against the post and
    tips the band over the back of the cradle, and a headset that leans forward
    in the pinch is pushed back by the cradle's front rim while it is lowered.
    Both show here as a band top outside the cradle's middle, before the hand opens.
    """
    name = 'cam_%s_wrist' % observer
    s = segment(robo, HEADSET_PROMPT, name)
    if s is None:
        return dict(ok=False, reason='headset not seen from the side')
    K, E = cam(robo, name)
    R = np.asarray(St['R'])
    centre = np.asarray(St['centre'])
    n = R[:, 0]
    tcp = np.asarray(robo.state().arm(holder).tcp_pos)
    rows, cols = np.nonzero(s['mask'])
    top = rows.min()
    sel = rows <= top + 2
    o, d = pixel_ray(K, E, (float(top), float(np.median(cols[sel]))))
    denom = float(d @ n)
    if abs(denom) < 0.3 or top <= 2:
        return dict(ok=False, reason='side view not usable for the band top')
    local = R.T @ (o + (float((tcp + 0 * n - o) @ n) / denom) * d - centre)
    return dict(ok=True, y=float(local[1]), z=float(local[2]), square=abs(denom), score=s['score'])


def grasp_cup(robo, H, arm='left', frames=None, own_axis=False):
    """Pinch the lying headset's left earcup from above and lift it. H = headset_cups()."""
    start = used(robo)
    out = []

    def snap():
        if frames is not None:
            frames.append(robo.image('cam_head'))

    def done(ok, reason=None, **kw):
        return dict(ok=ok, reason=reason, replies=out, actions=used(robo) - start, **kw)

    cup = np.asarray(H['left'])
    yaw_g = H['yaw_deg']
    close = cup_closeup(robo, cup, arm=arm, which='left', prior_yaw=None if own_axis else yaw_g)
    out.append(dict(label='cup-closeup', ok=close.get('ok'), reason=close.get('reason'), actions=close.get('actions'), looks=close.get('looks'),
                    centre=None if 'centre' not in close else np.round(close['centre'][:2], 3).tolist(),
                    finger_yaw=None if 'finger_yaw_deg' not in close else round(close['finger_yaw_deg'], 1))); snap()
    if close.get('ok'):
        cup = np.array([close['centre'][0], close['centre'][1], cup[2]])
        yaw_g = close['finger_yaw_deg']
    pitch = float(robo.state().arm(arm).pitch)
    above_z = _carry_z()
    fine = True
    for zz in (above_z, CUP_GRASP_Z):
        pv = robo.preview_move([float(cup[0]), float(cup[1]), zz], arm=arm, path='auto', pitch=pitch, yaw=yaw_g, roll=0)
        fine = fine and bool(pv.get('reachable')) and not pv.get('ik_error') and not pv.get('note')
    if not fine:
        return done(False, 'earcup out of reach for this arm')
    out.append(approach(robo, arm, [cup[0], cup[1], above_z], opening=1.0, pitch=pitch, yaw=yaw_g, roll=0, path='auto', label='above-cup')); snap()
    if not out[-1]['reached']:
        return done(False, 'above-cup not reached')
    out.append(go(robo, arm, [cup[0], cup[1], HANG_GRASP_Z], pitch=pitch, yaw=yaw_g, roll=0, label='descend')); snap()
    if not out[-1]['reached'] and float(robo.state().arm(arm).tcp_pos[2]) > CUP_GRASP_Z + 0.004:
        return done(False, 'descent blocked')
    g = robo.set_gripper(arm, robo.CLOSE)
    out.append(dict(label='close', holding=bool(g.holding), width=g.width_m, opening=g.opening, actions=g.steps_used, pitch=pitch)); snap()
    if not g.holding:
        return done(False, 'earcup not held')
    out.append(go(robo, arm, [cup[0], cup[1], above_z], pitch=pitch, yaw=yaw_g, roll=0, gripper=robo.CLOSE, label='lift')); snap()
    if not out[-1]['reached']:
        return done(False, 'lift not reached')
    lifted = float(robo.state().arm(arm).gripper)
    out.append(dict(label='pinch-test', closed=round(float(g.opening), 3), lifted=round(lifted, 3), holding=bool(g.holding)))
    return done(True, grasp_yaw=yaw_g, grasp_pitch=pitch)


def carry_and_hang(robo, St, arm='left', frames=None):
    """From a held earcup: turn the headset upright, carry it to the stand, hang it, check it.

    St = stand_pose() from before the headset was moved. The band apex is
    measured in free space near the stand and decides where the band is set
    down; the hanging earcups are measured afterwards as the postcondition.
    """
    start = used(robo)
    out = []

    def snap():
        if frames is not None:
            frames.append(robo.image('cam_head'))

    def done(ok, reason=None, **kw):
        return dict(ok=ok, reason=reason, replies=out, actions=used(robo) - start, **kw)

    def lost(where):
        """True once the earcup has slid out of the pinch (the fingers have closed on nothing): stop at once, the
        hand must not sweep on over the stand and push the fallen headset about."""
        if float(robo.state().arm(arm).gripper) > 0.03:
            return False
        out.append(dict(label='headset-lost', after=where, at=used(robo)))
        return True

    th = St['yaw_deg']
    R = np.asarray(St['R'])
    centre = np.asarray(St['centre'])
    half = float(min(CRADLE_DIMS)) / 2.0
    s0 = robo.state().arm(arm)
    carry_z = _carry_z()
    out.append(glide(robo, arm, [[float(v) for v in s0.tcp_pos][0], [float(v) for v in s0.tcp_pos][1], carry_z], step_m=0.02, pitch=s0.pitch, yaw=s0.yaw, roll=s0.roll,
                     gripper=robo.CLOSE, label='to-turn-spot')); snap()
    if lost('to-turn-spot'):
        return done(False, 'headset left the hand during the carry')
    hang_pitch, hang_yaw, hang_roll = float(s0.pitch), float(th), float(s0.roll)
    kw = dict(pitch=hang_pitch, yaw=hang_yaw, roll=hang_roll, gripper=robo.CLOSE)
    for k in range(1, 7):
        f = k / 6.0
        rec = go(robo, arm, [[float(v) for v in s0.tcp_pos][0], [float(v) for v in s0.tcp_pos][1], carry_z + f * ([float(v) for v in s0.tcp_pos][2] - carry_z)], path='auto', gripper=robo.CLOSE,
                 pitch=s0.pitch + f * (hang_pitch - s0.pitch), yaw=s0.yaw + f * (hang_yaw - s0.yaw), roll=s0.roll + f * (hang_roll - s0.roll), label='upright')
    out.append(dict(rec, at=used(robo))); snap()
    if not rec['reached']:
        return done(False, 'upright pose not reached')
    if lost('upright'):
        return done(False, 'headset left the hand during the carry')

    def stand_point(x, y, z):
        return centre + R @ np.array([x, y, z])

    def set_down(reason):
        """Turn the headset back, carry it to where it was picked up, set it down and let go; the stage then measures it
        on the table and takes it again, which gives a new pinch and a new side view."""
        hp, hy, hr = hang_pitch, hang_yaw, hang_roll
        rec = None
        for k in range(5, -1, -1):
            f = k / 6.0
            rec = go(robo, arm, [[float(v) for v in s0.tcp_pos][0], [float(v) for v in s0.tcp_pos][1], carry_z + f * ([float(v) for v in s0.tcp_pos][2] - carry_z)], path='auto', gripper=robo.CLOSE,
                     pitch=s0.pitch + f * (hp - s0.pitch), yaw=s0.yaw + f * (hy - s0.yaw), roll=s0.roll + f * (hr - s0.roll), label='turn-back')
        out.append(dict(rec, at=used(robo))); snap()
        if not lost('turn-back'):
            home_xy = [float(s0.tcp_pos[0]), float(s0.tcp_pos[1])]
            out.append(glide(robo, arm, home_xy + [carry_z], step_m=0.02, pitch=s0.pitch, yaw=s0.yaw, roll=s0.roll, gripper=robo.CLOSE, label='carry-back')); snap()
            out.append(glide(robo, arm, home_xy + [CUP_GRASP_Z], step_m=0.02, pitch=s0.pitch, yaw=s0.yaw, roll=s0.roll,
                             gripper=robo.CLOSE, label='set-down')); snap()
            g = robo.set_gripper(arm, robo.OPEN)
            out.append(dict(label='open', opening=g.opening, actions=g.steps_used))
            out.append(glide(robo, arm, home_xy + [carry_z], step_m=0.03, pitch=s0.pitch, yaw=s0.yaw, roll=s0.roll, label='set-down-up')); snap()
        pst = robo.state().arm('right')
        out.append(approach(robo, 'right', _here(robo, 'right'), opening=1.0, pitch=float(pst.pitch), yaw=float(pst.yaw), roll=float(pst.roll), path='auto', label='observer-park'))
        return done(False, reason)

    opening_now = float(robo.state().arm(arm).gripper)
    out.append(dict(label='pinch-check', opening_at_lift=round(float(s0.gripper), 3), opening_upright=round(opening_now, 3)))

    look = side_look(robo, St, holder=arm)
    out.append(dict(label='side-look', ok=look.get('ok'), reason=look.get('reason'), actions=look.get('actions'), found_by=look.get('found_by'),
                    ahead=None if 'ahead' not in look else round(look['ahead'], 3),
                    apex_up=None if 'apex_up' not in look else round(look['apex_up'], 3))); snap()
    before = dict(look=look, angles=(hang_pitch, hang_yaw, hang_roll))
    turned = False
    for _ in range(2):
        if not look.get('ok'):
            break
        lean = math.degrees(math.atan2(look['ahead'], look['apex_up']))
        tcp_now = np.asarray(robo.state().arm(arm).tcp_pos, float)
        rel = np.asarray(look['apex'], float) - tcp_now
        cur = orientation(hang_pitch, hang_yaw, hang_roll)
        best = None
        for sgn in (1.0, -1.0):
            new = cur @ _ry(math.radians(sgn * abs(lean)))
            moved = new @ cur.T @ rel
            resid = abs(math.degrees(math.atan2(float(moved @ R[:, 1]), float(moved[2]))))
            if best is None or resid < best[0]:
                best = (resid, sgn)
        sgn = best[1]
        turn = None
        full = abs(lean)
        for cand in (full, full - 10.0, full - 20.0, full - 30.0):
            if cand < 8.0:
                break
            pc, yc, rc = angles(cur @ _ry(math.radians(sgn * cand)))
            fine = True
            for q in (tcp_now, stand_point(0.0, -half, 0.0), stand_point(0.0, 0.0, 0.0)):
                pv = robo.preview_move([float(v) for v in q], arm=arm, path='auto', pitch=pc, yaw=yc, roll=rc)
                fine = fine and bool(pv.get('reachable')) and not pv.get('ik_error')
            if fine:
                turn = cand
                break
        if turn is None:
            out.append(dict(label='stand-up', applied=False, lean_deg=round(lean, 1), reason='no turned release pose within reach'))
            break
        p2, y2, r2 = angles(cur @ _ry(math.radians(sgn * turn)))
        n = max(1, int(math.ceil(turn / 6.0)))
        rec = None
        for k in range(1, n + 1):
            pk, yk, rk = angles(cur @ _ry(math.radians(sgn * turn * k / n)))
            rec = go(robo, arm, tcp_now, path='auto', gripper=robo.CLOSE, pitch=pk, yaw=yk, roll=rk, label='stand-up')
            if not rec['reached']:
                break
        if rec['reached']:
            hang_pitch, hang_yaw, hang_roll = p2, y2, r2
        else:
            st = robo.state().arm(arm)
            hang_pitch, hang_yaw, hang_roll = float(st.pitch), float(st.yaw), float(st.roll)
        kw = dict(pitch=hang_pitch, yaw=hang_yaw, roll=hang_roll, gripper=robo.CLOSE)
        turned = True
        out.append(dict(rec, label='stand-up', applied=True, lean_deg=round(lean, 1), turn_deg=round(sgn * turn, 1), partial=bool(turn < full - 0.5), at=used(robo))); snap()
        look = side_look(robo, St, holder=arm)
        out.append(dict(label='side-look', ok=look.get('ok'), reason=look.get('reason'), actions=look.get('actions'), found_by=look.get('found_by'),
                        ahead=None if 'ahead' not in look else round(look['ahead'], 3),
                        apex_up=None if 'apex_up' not in look else round(look['apex_up'], 3))); snap()
        if turn < full - 0.5:
            break
    if not look.get('ok'):
        return set_down('headset not measured from the side: set down for a new grasp')
    hang_x = 0.0
    tcp_y = 0.0
    z_seat = float(look['centre_up'])
    z_arrive = float(look.get('apex_up', z_seat))
    if look.get('ok') and 'ahead' in look:
        tcp_y = float(np.clip(-look['ahead'], -half, half))
    pre = stand_point(hang_x, tcp_y - half, z_arrive)
    out.append(glide(robo, arm, pre, label='pre-stand', **kw)); snap()
    if lost('pre-stand'):
        return done(False, 'headset left the hand during the carry')
    if not out[-1]['reached'] and turned:
        hang_pitch, hang_yaw, hang_roll = before['angles']
        kw = dict(pitch=hang_pitch, yaw=hang_yaw, roll=hang_roll, gripper=robo.CLOSE)
        out.append(glide(robo, arm, [float(v) for v in s0.tcp_pos], step_m=0.02, label='turn-back', **kw)); snap()
        look = before['look']
        tcp_y = float(np.clip(-look['ahead'], -half, half))
        z_seat = float(look['centre_up'])
        z_arrive = float(look.get('apex_up', z_seat))
        pre = stand_point(hang_x, tcp_y - half, z_arrive)
        out.append(glide(robo, arm, pre, label='pre-stand', **kw)); snap()
    if not out[-1]['reached']:
        return done(False, 'pre-stand not reached')
    out.append(glide(robo, arm, stand_point(hang_x, tcp_y, z_arrive), step_m=0.012, label='over-stand', **kw)); snap()
    if lost('over-stand'):
        return done(False, 'headset left the hand during the carry')
    at = R.T @ (np.asarray(robo.state().arm(arm).tcp_pos) - centre)
    if not out[-1]['reached'] and abs(at[1] - tcp_y) > 0.02:
        return done(False, 'over-stand not reached')
    hang = stand_point(float(at[0]), float(at[1]), z_seat)
    out.append(glide(robo, arm, hang, step_m=0.012, label='lower', **kw)); snap()
    if lost('lower'):
        return done(False, 'headset left the hand during the carry')
    empty = False
    for attempt in range(3):
        band = held_band_look(robo, St, holder=arm)
        out.append(dict(label='band-look', ok=band.get('ok'), reason=band.get('reason'), attempt=attempt,
                        y=None if 'y' not in band else round(band['y'], 3), z=None if 'z' not in band else round(band['z'], 3))); snap()
        if not band.get('ok') or attempt == 2:
            break
        shift = float(-band['y'])
        at = R.T @ (np.asarray(robo.state().arm(arm).tcp_pos) - centre)
        out.append(glide(robo, arm, stand_point(float(at[0]), float(at[1]), z_arrive), step_m=0.012, label='re-lift', **kw)); snap()
        if lost('re-lift'):
            empty = True
            break
        out.append(dict(glide(robo, arm, stand_point(float(at[0]), float(at[1]) + shift, z_arrive), step_m=0.012, label='re-aim', **kw),
                        shift=round(shift, 3))); snap()
        if lost('re-aim'):
            empty = True
            break
        at = R.T @ (np.asarray(robo.state().arm(arm).tcp_pos) - centre)
        hang = stand_point(float(at[0]), float(at[1]), z_seat)
        out.append(glide(robo, arm, hang, step_m=0.012, label='lower', **kw)); snap()
    if empty:
        back = np.asarray(robo.state().arm(arm).tcp_pos, float) + R @ np.array([0.0, -half, 0.0])
        out.append(glide(robo, arm, back, step_m=0.025, pitch=hang_pitch, yaw=hang_yaw, roll=hang_roll, gripper=robo.CLOSE, label='retreat')); snap()
        g = robo.set_gripper(arm, robo.OPEN)
        out.append(dict(label='open', opening=g.opening, actions=g.steps_used)); snap()
    else:
        g = robo.set_gripper(arm, robo.OPEN)
        out.append(dict(label='open', opening=g.opening, actions=g.steps_used)); snap()
        out.append(glide(robo, arm, hang + R @ np.array([0.0, -half, 0.0]), step_m=0.025, pitch=hang_pitch, yaw=hang_yaw, roll=hang_roll, label='retreat')); snap()
    side = side_check(robo, St)
    head = hung_offset(robo, St, St['mask']['mask'])
    seated = bool(side.get('seated')) if side.get('ok') else False
    out.append(dict(label='post-hang', seated=seated, side_ok=side.get('ok'), reason=side.get('reason'),
                    band_top=None if 'band_top_in_stand' not in side else np.round(side['band_top_in_stand'], 3).tolist(),
                    head_offset_px=None if 'offset_px' not in head else round(head['offset_px'], 1)))
    pst = robo.state().arm('right')
    out.append(approach(robo, 'right', _here(robo, 'right'), opening=1.0, pitch=float(pst.pitch), yaw=float(pst.yaw), roll=float(pst.roll), path='auto', label='observer-park'))
    return done(seated, None if seated else 'headset not measured hanging on the stand', hang_tcp=hang)


def relocate_headset(robo, H, arm='right', frames=None):
    """Move a far-side lying headset sideways into the left arm's reach, without turning it.

    The right arm pinches the right earcup from above, lifts, carries the
    headset along x and sets it down at the same height, then parks again over
    the rack. H = headset_cups().
    """
    start = used(robo)
    out = []

    def snap():
        if frames is not None:
            frames.append(robo.image('cam_head'))

    def done(ok, reason=None, **kw):
        return dict(ok=ok, reason=reason, replies=out, actions=used(robo) - start, **kw)

    cup = np.asarray(H['right'])
    yaw_g = H['yaw_deg']
    close = cup_closeup(robo, cup, arm=arm, which='right', prior_yaw=yaw_g)
    out.append(dict(label='cup-closeup', ok=close.get('ok'), reason=close.get('reason'), actions=close.get('actions'), looks=close.get('looks'),
                    centre=None if 'centre' not in close else np.round(close['centre'][:2], 3).tolist(),
                    finger_yaw=None if 'finger_yaw_deg' not in close else round(close['finger_yaw_deg'], 1))); snap()
    if close.get('ok'):
        cup = np.array([close['centre'][0], close['centre'][1], cup[2]])
        yaw_g = close['finger_yaw_deg']
    above_z = _carry_z()
    kw = dict(pitch=float(robo.state().arm(arm).pitch), yaw=yaw_g, roll=0)
    out.append(approach(robo, arm, [cup[0], cup[1], above_z], opening=1.0, path='auto', label='above-cup', **kw)); snap()
    if not out[-1]['reached']:
        return done(False, 'above-cup not reached')
    out.append(go(robo, arm, [cup[0], cup[1], CUP_GRASP_Z], label='descend', **kw)); snap()
    g = robo.set_gripper(arm, robo.CLOSE)
    out.append(dict(label='close', holding=bool(g.holding), width=g.width_m, actions=g.steps_used)); snap()
    if not g.holding:
        return done(False, 'earcup not held')
    dx = 0.0
    out.append(go(robo, arm, [cup[0], cup[1], above_z], gripper=robo.CLOSE, label='lift', **kw)); snap()
    out.append(glide(robo, arm, [cup[0] + dx, cup[1], above_z], step_m=0.02, gripper=robo.CLOSE, label='carry', **kw)); snap()
    if not out[-1]['reached']:
        return done(False, 'carry not completed')
    out.append(glide(robo, arm, [cup[0] + dx, cup[1], CUP_GRASP_Z], step_m=0.012, gripper=robo.CLOSE, label='set-down', **kw)); snap()
    g = robo.set_gripper(arm, robo.OPEN)
    out.append(dict(label='open', opening=g.opening, actions=g.steps_used))
    out.append(glide(robo, arm, [cup[0] + dx, cup[1], above_z], step_m=0.02, gripper=robo.OPEN, label='clear', **kw)); snap()
    if float(robo.state().arm(arm).tcp_pos[2]) <= CUP_GRASP_Z:
        return done(False, 'hand not clear of the headset after set-down')
    pst = robo.state().arm(arm)
    out.append(go(robo, arm, _here(robo, arm), pitch=float(pst.pitch), yaw=float(pst.yaw), roll=float(pst.roll), gripper=robo.OPEN, path='auto', label='away')); snap()
    out.append(approach(robo, arm, _here(robo, arm), opening=1.0, pitch=float(pst.pitch), yaw=float(pst.yaw), roll=float(pst.roll), path='auto', label='park')); snap()
    return done(True, moved_x=dx)


def hang_headset(robo, H, St, arm='left', frames=None, own_axis=False):
    """Grasp the lying headset by its left earcup, then carry and hang it."""
    g = grasp_cup(robo, H, arm=arm, frames=frames, own_axis=own_axis)
    if not g['ok']:
        return dict(ok=False, reason=g['reason'], replies=g['replies'], actions=g['actions'], step='grasp')
    c = carry_and_hang(robo, St, arm=arm, frames=frames)
    return dict(ok=c['ok'], reason=c['reason'], replies=g['replies'] + c['replies'], actions=g['actions'] + c['actions'],
                step='carry', hang_tcp=c.get('hang_tcp'))


RACK_PLATE_Z = TABLE_Z
# Measured laptop rack footprint.
RACK_PLATE_DIMS = (0.130, 0.051)


def white_mask(rgb, max_sat=45, min_val=75):
    """Unsaturated, not dark pixels: the rack's brushed-metal base plate against the wooden table.

    The plate reads anywhere from bright white to mid grey depending on how it
    catches the light, so brightness alone does not find it; its lack of colour does.
    """
    import cv2
    hsv = cv2.cvtColor(np.ascontiguousarray(np.asarray(rgb)[:, :, :3]), cv2.COLOR_RGB2HSV)
    return (hsv[:, :, 1] < max_sat) & (hsv[:, :, 2] > min_val)


def plate_rect(robo, camera):
    """White base plate rectangle on the table plane seen from one camera.

    Other pale things can be in view (a light headset, the robot). Each white
    connected region is fitted on its own and the one whose size matches the
    plate is used.
    """
    import cv2
    K, E = cam(robo, camera)
    w = white_mask(robo.image(camera)).astype(np.uint8)
    w = cv2.morphologyEx(w, cv2.MORPH_OPEN, np.ones((3, 3), np.uint8))
    n, lab, stats, _ = cv2.connectedComponentsWithStats(w)
    best = None
    for i in range(1, n):
        if stats[i, cv2.CC_STAT_AREA] < 60:
            continue
        rows, cols = np.nonzero(lab == i)
        step = max(1, len(rows) // 4000)
        pts = np.array([ray_at_z(K, E, (r, c), RACK_PLATE_Z)[:2] for r, c in zip(rows[::step], cols[::step])])
        r = min_area_rect(pts)
        miss = abs(r['dims'][1] - RACK_PLATE_DIMS[1]) + 0.3 * max(0.0, 0.5 * RACK_PLATE_DIMS[0] - r['dims'][0]) + max(0.0, r['dims'][0] - RACK_PLATE_DIMS[0] - 0.5 * RACK_PLATE_DIMS[1])
        if best is None or miss < best[0]:
            best = (miss, r, pts)
    if best is None:
        return dict(ok=False, reason='no white region in the rack area', camera=camera)
    _, r, pts = best
    yaw = math.degrees(r['angle'])
    if yaw < 0:
        yaw += 180.0
    along = np.array([math.cos(math.radians(yaw)), math.sin(math.radians(yaw))])
    t = pts @ along
    centre = r['centre'] + along * ((float(np.percentile(t, 1)) + RACK_PLATE_DIMS[0] / 2) - float(r['centre'] @ along))
    ok = 0.09 < r['dims'][0] < RACK_PLATE_DIMS[0] + 0.02 and abs(r['dims'][1] - RACK_PLATE_DIMS[1]) < 0.012
    return dict(ok=bool(ok), centre=np.array([centre[0], centre[1], RACK_PLATE_Z]), yaw_deg=yaw,
                dims=r['dims'], corners=r['corners'], n=int(len(pts)), camera=camera)
def _here(robo, arm):
    """The hand's current position. Survey and park views start from here."""
    return np.asarray(robo.state().arm(arm).tcp_pos, float)


RACK_SAM_PROMPTS = ('white rectangular plate', 'white tray', 'card holder', 'two wooden boards')
def mask_rect_xy(robo, mask, camera, z):
    """Table-plane rectangle (centre, (long, short), long-axis yaw in [0, 180)) of a mask's pixels placed at height z."""
    K, E = cam(robo, camera)
    rows, cols = np.nonzero(mask)
    if len(rows) < 30:
        return None
    step = max(1, len(rows) // 3000)
    pts = np.array([ray_at_z(K, E, (r, c), z)[:2] for r, c in zip(rows[::step], cols[::step])])
    r = min_area_rect(pts)
    yaw = math.degrees(r['angle'])
    if yaw < 0:
        yaw += 180.0
    return dict(centre=np.asarray(r['centre'], float), dims=(float(r['dims'][0]), float(r['dims'][1])), yaw=yaw)


def plate_from_prompts(robo, camera):
    """The rack's base plate from text-prompted masks, accepted only by shape and place (no colour test)."""
    cands = []
    for prompt in RACK_SAM_PROMPTS:
        s = segment(robo, prompt, camera=camera, min_score=0.03)
        if s is None:
            continue
        r = mask_rect_xy(robo, s['mask'], camera, RACK_PLATE_Z)
        if r is None:
            continue
        L, W = r['dims']
        kind = None
        if abs(L - RACK_PLATE_DIMS[0]) < 0.012 and abs(W - RACK_PLATE_DIMS[1]) < 0.009:
            kind = 'plate'
        cands.append(dict(prompt=prompt, score=round(float(s['score']), 3), kind=kind,
                          centre=[round(float(v), 4) for v in r['centre']], dims=[round(L, 4), round(W, 4)], yaw=round(r['yaw'], 1)))
    for kind in ('plate', 'slats'):
        good = [c for c in cands if c['kind'] == kind]
        if not good:
            continue
        best = max(good, key=lambda c: c['score'])
        agree = [c for c in good if np.linalg.norm(np.subtract(c['centre'], best['centre'])) < 0.006 and abs(c['yaw'] - best['yaw']) < 3.0]
        centre = np.mean([c['centre'] for c in agree], axis=0)
        yaw = float(np.mean([c['yaw'] for c in agree]))
        return dict(ok=True, centre=np.array([centre[0], centre[1], RACK_PLATE_Z]), yaw_deg=yaw, dims=best['dims'], kind=kind,
                    prompts=[c['prompt'] for c in agree], candidates=cands, camera=camera)
    return dict(ok=False, reason='no plate-shaped mask in the rack area', candidates=cands, camera=camera)


def rack_survey(robo, arm='right'):
    """Wrist-camera fit of the rack's base plate from the arm's current pose.

    The plate is fitted by its lack of colour. When that fails, or a
    text-prompted plate of the measured footprint disagrees with it, the
    prompted plate is used.
    """
    start = used(robo)
    name = 'cam_%s_wrist' % arm
    st = robo.state().arm(arm)
    rec = approach(robo, arm, _here(robo, arm), opening=1.0, pitch=float(st.pitch), yaw=float(st.yaw), roll=float(st.roll), path='auto', label='rack-survey')
    fine = plate_rect(robo, name)
    alt = plate_from_prompts(robo, name)
    method = 'colour'
    if fine.get('ok'):
        if alt.get('ok') and alt['kind'] == 'plate' and np.linalg.norm(np.asarray(alt['centre'][:2]) - np.asarray(fine['centre'][:2])) > 0.012:
            fine, method = alt, 'prompted plate (colour fit disagreed)'
    else:
        if not alt.get('ok') and rec['reached']:
            alt = plate_from_prompts(robo, name)
        if alt.get('ok'):
            fine, method = alt, 'prompted ' + alt['kind']
    return dict(ok=bool(rec['reached'] and fine.get('ok')), fine=fine, colour_fit_ok=bool(plate_rect is not None and method == 'colour' and fine.get('ok')),
                method=method, prompted=dict((k, v) for k, v in alt.items() if k != 'centre'), reply=rec,
                centre=fine.get('centre'), yaw_deg=fine.get('yaw_deg'), actions=used(robo) - start)


# Geometry fit. docs/store_laptop_and_headphones/geometry_fit.json
LAPTOP_MID_Z = 0.8471




def heading_deg(v):
    """Gripper yaw (0 = +y, +90 = -x) of a horizontal direction."""
    return math.degrees(math.atan2(-v[0], v[1]))


def pick_laptop(robo, P, arm='left', frames=None, overhang=None):
    """Pinch the closed laptop's front lip, work it forward, re-pinch deeper, lift and present it.

    P = closed_laptop_pose(). The pinch is at the measured front edge. A measured
    overhang is pulled by that amount. The lift is one quarter of the measured
    laptop depth. After the pinch the hand must still be holding.
    """
    start = used(robo)
    out = []

    def snap():
        if frames is not None:
            frames.append(robo.image('cam_head'))

    def done(ok, reason=None, **kw):
        return dict(ok=ok, reason=reason, replies=out, actions=used(robo) - start, **kw)

    x, y = P['x_dir'], P['y_dir']
    yaw = heading_deg(y)
    f = np.array([P['front'][0], P['front'][1], LAPTOP_MID_Z])
    kw = dict(pitch=float(robo.state().arm(arm).pitch), yaw=yaw, roll=90.0)

    def at(depth):
        """TCP this far past the laptop's measured front edge."""
        return f + y * depth

    def pinch(label):
        g = robo.set_gripper(arm, robo.CLOSE)
        ok = bool(g.holding)
        out.append(dict(label=label, holding=bool(g.holding), width=g.width_m, actions=g.steps_used)); snap()
        return ok

    def still_holding():
        return float(robo.state().arm(arm).gripper) > 0.03

    step = _measured_step()
    out.append(approach(robo, arm, at(-float(LAPTOP_DIMS[1]) / 2.0) + [0, 0, step], opening=1.0, path='auto', label='pre-lip', **kw)); snap()
    if not out[-1]['reached']:
        return done(False, 'pre-lip not reached')
    out.append(go(robo, arm, at(0.0), label='at-lip', **kw))
    out.append(go(robo, arm, at(0.0), label='on-lip', **kw)); snap()
    if not pinch('pinch'):
        return done(False, 'front lip not pinched')
    need = 0.0 if overhang is None else max(0.0, -float(overhang))
    pull = max(0.0, float(need))
    out.append(dict(label='overhang', measured=None if overhang is None else round(float(overhang), 3), pull_m=round(pull, 4)))
    pulled = 0.0
    depth = 0.0
    if pull > 0.0:
        out.append(glide(robo, arm, at(depth - pull), step_m=_measured_step(), gripper=robo.CLOSE, label='pull', **kw)); snap()
        if not still_holding():
            return done(False, 'lip slipped out during pull', pulled=pull)
        pulled = pull
    depth = depth - pulled
    out.append(go(robo, arm, at(depth) + [0, 0, step], gripper=robo.CLOSE, label='lift', **kw)); snap()
    if not out[-1]['reached'] or not still_holding():
        return done(False, 'lift not completed with the laptop', pulled=pulled)
    return done(True, pulled=pulled)
def deeper_so_far(stage):
    """Pinch depth beyond the first one that has been gained before pull number ``stage``."""
    return 0.0


def return_to_riser(robo, P, arm='left', frames=None):
    """Lay a held laptop back on the riser where it came from and let go (recovery).

    P is the pose it was picked from. The laptop is brought back over the riser
    in the pinch orientation, lowered until it lies on the riser, released, and
    the hand backs straight out.
    """
    start = used(robo)
    out = []
    x, y = P['x_dir'], P['y_dir']
    yaw = heading_deg(y)
    f = np.array([P['front'][0], P['front'][1], LAPTOP_MID_Z])
    kw = dict(pitch=float(robo.state().arm(arm).pitch), yaw=yaw, roll=90.0)
    step = _measured_step()
    base = f
    out.append(go(robo, arm, base + [0, 0, step], gripper=robo.CLOSE, path='auto', label='back-over-riser', **kw))
    out.append(glide(robo, arm, base, step_m=step, gripper=robo.CLOSE, label='lay-down', **kw))
    g = robo.set_gripper(arm, robo.OPEN)
    out.append(dict(label='release', opening=g.opening, actions=g.steps_used))
    out.append(glide(robo, arm, base - y * float(LAPTOP_DIMS[1]) + [0, 0, step], step_m=step, gripper=robo.OPEN, label='back-out', **kw))
    out.append(go(robo, arm, base - y * float(LAPTOP_DIMS[1]) + [0, 0, step], gripper=robo.OPEN, label='clear-view', **kw))
    if frames is not None:
        frames.append(robo.image('cam_head'))
    return dict(ok=bool(out[-1]['reached']), replies=out, actions=used(robo) - start)


def held_laptop_pose(robo, donor='left'):
    """Pose of the presented laptop: head-view rectangle, hinge side along the donor's heading."""
    st = robo.state().arm(donor)
    a = math.radians(st.yaw)
    heading = np.array([-math.sin(a), math.cos(a)])
    return closed_laptop_pose(robo, top_z=float(st.tcp_pos[2]) + 0.005, toward=heading)


def hand_over(robo, Q, donor='left', receiver='right', frames=None):
    """Receiver pinches over the hinge edge; donor lets go and backs away. Q = held_laptop_pose()."""
    start = used(robo)
    out = []

    def snap():
        if frames is not None:
            frames.append(robo.image('cam_head'))

    def done(ok, reason=None, **kw):
        return dict(ok=ok, reason=reason, replies=out, actions=used(robo) - start, **kw)

    x, y = Q['x_dir'], Q['y_dir']
    z = float(robo.state().arm(donor).tcp_pos[2])
    a = y / np.linalg.norm(y)
    tcp = np.array([Q['front'][0], Q['front'][1], z])
    tcp[2] = z
    kw = dict(pitch=float(robo.state().arm(receiver).pitch), yaw=heading_deg(a), roll=90.0)
    out.append(approach(robo, receiver, tcp - a * _measured_step(), opening=1.0, path='auto', label='receiver-pre', **kw)); snap()
    if not out[-1]['reached']:
        return done(False, 'receiver pre-grasp not reached', target=tcp, yaw=kw['yaw'])
    out.append(go(robo, receiver, tcp, label='receiver-in', **kw)); snap()
    g = robo.set_gripper(receiver, robo.CLOSE)
    out.append(dict(label='receiver-pinch', holding=bool(g.holding), width=g.width_m, actions=g.steps_used)); snap()
    if not g.holding:
        return done(False, 'receiver not holding the laptop')
    g = robo.set_gripper(donor, robo.OPEN, opening=0.5)
    out.append(dict(label='donor-release', opening=g.opening, actions=g.steps_used))
    sd = robo.state().arm(donor)
    ad = math.radians(sd.yaw)
    back = np.asarray(sd.tcp_pos) - float(LAPTOP_DIMS[1]) / 2.0 * np.array([-math.sin(ad), math.cos(ad), 0.0])
    out.append(go(robo, donor, back, pitch=sd.pitch, yaw=sd.yaw, roll=sd.roll, label='donor-back')); snap()
    return done(True, receiver_tcp=tcp, receiver_yaw=kw['yaw'])
RACK_FLOOR_Z = TABLE_Z
# Rail height above RACK_FLOOR_Z. docs/store_laptop_and_headphones/applied_values.json
RACK_WALL_TOP = 0.04541018468951186


def held_offset(robo, arm='right', rows=(40, 220)):
    """How far the held laptop sits from the gripper's centre plane, from the wrist view.

    The gripper's two fingers close independently, so a held plate is not
    centred between them. Seen edge-on by the wrist camera the laptop is a
    vertical band; its centre relative to the image centre, in units of its own
    width, is its offset in units of its thickness. No depth is needed.
    Returns the offset in metres along the image's +column direction and that
    direction in the world.
    """
    import cv2
    name = 'cam_%s_wrist' % arm
    rgb = np.ascontiguousarray(np.asarray(robo.image(name))[:, :, :3])
    K, E = cam(robo, name)
    hsv = cv2.cvtColor(rgb, cv2.COLOR_RGB2HSV)
    plain = (hsv[:, :, 1] < 70)
    cx = int(round(K[0, 2]))
    vals = []
    for r in range(rows[0], rows[1], 4):
        line = plain[r]
        idx = np.nonzero(line)[0]
        if len(idx) == 0:
            continue
        splits = np.nonzero(np.diff(idx) > 2)[0]
        runs = np.split(idx, splits + 1)
        runs = [u for u in runs if 12 <= len(u) <= 220]
        if not runs:
            continue
        u = min(runs, key=lambda u: abs((u[0] + u[-1]) / 2 - cx))
        centre, width = (u[0] + u[-1]) / 2.0, float(u[-1] - u[0] + 1)
        if abs(centre - cx) < 120:
            vals.append((0.0, width))
    if len(vals) < 8:
        return dict(ok=False, reason='laptop band not found in the wrist view', rows=len(vals))
    off = float(np.median([v[0] for v in vals]))
    spread = float(np.percentile([v[0] for v in vals], 80) - np.percentile([v[0] for v in vals], 20))
    return dict(ok=bool(spread < 0.004), offset=off, spread=spread, width_px=float(np.median([v[1] for v in vals])),
                rows=len(vals), column_dir=E[:3, 0].copy())
def edge_view(robo, arm='right'):
    """Where the held laptop's LOWER edge is, sideways from the hand, seen from the wrist camera.

    In the insertion pose the wrist camera looks down along the hanging
    laptop. The black hinge strip is a narrow dark band; its column gives the
    hinge edge's sideways offset in the hand. A laptop that leans in the
    pinch shows one of its silver faces beside the strip, and the width of
    that face gives how far the lower edge is displaced from the hinge edge.
    Only the far rows of the strip are used: there the background is the
    table beyond the rack, not the white rack.
    Returns the lower edge's offset in metres along the
    image's +column direction and that direction in the world.
    """
    import cv2
    name = 'cam_%s_wrist' % arm
    rgb = np.ascontiguousarray(np.asarray(robo.image(name))[:, :, :3])
    K, E = cam(robo, name)
    hsv = cv2.cvtColor(rgb, cv2.COLOR_RGB2HSV)
    dark = hsv[:, :, 2] < 70
    plain = hsv[:, :, 1] < 70
    cx = float(K[0, 2])
    found = []
    for r in range(16, 262, 4):
        idx = np.nonzero(dark[r])[0]
        if len(idx) == 0:
            continue
        runs = np.split(idx, np.nonzero(np.diff(idx) > 2)[0] + 1)
        runs = [u for u in runs if 12 <= len(u) <= 80 and abs((u[0] + u[-1]) / 2 - cx) < 110]
        if not runs:
            continue
        u = min(runs, key=lambda u: abs((u[0] + u[-1]) / 2 - cx))
        lo, hi = int(u[0]), int(u[-1])
        a = lo - 1
        while a >= 0 and plain[r, a] and not dark[r, a]:
            a -= 1
        b = hi + 1
        while b < dark.shape[1] and plain[r, b] and not dark[r, b]:
            b += 1
        found.append((r, (lo + hi) / 2.0, hi - lo + 1, lo - 1 - a, b - hi - 1))
    if len(found) < 12:
        return dict(ok=False, reason='hinge strip not found in the wrist view', rows=len(found))
    found = np.array(found, float)
    c = float(np.median(found[:, 1]))
    keep = found[np.abs(found[:, 1] - c) < 14]
    if len(keep) < 12:
        return dict(ok=False, reason='hinge strip not straight in the wrist view', rows=len(keep))
    far = keep[:16]
    left, right = float(np.median(far[:, 3])), float(np.median(far[:, 4]))
    strip = float(np.median(keep[:, 2]))
    z_ref = float(robo.state().arm(arm).tcp_pos[2])
    row_ref = float(np.median(far[:, 0]))
    col_ref = float(K[0, 2])
    origin = ray_at_z(K, E, (row_ref, col_ref), z_ref)
    at_strip = ray_at_z(K, E, (row_ref, c), z_ref)
    offset = float((at_strip - origin) @ E[:3, 0])
    return dict(ok=True, offset=offset, lean_mm=0.0, hinge_mm=offset * 1000.0, left_px=left, right_px=right,
                strip_col=c, strip_px=strip, rows=len(keep), column_dir=E[:3, 0].copy())


def insert_laptop(robo, Rk, arm='right', frames=None):
    """Carry the laptop to the measured rack and lower it to the published rail height.

    Rk = rack_survey(): slot centre and yaw. A wrist view can shift the hand
    by the dark strip's measured offset from the optical axis. The lean
    regression is not used. The hand opens at the rail and withdraws.
    """
    start = used(robo)
    out = []

    def snap():
        if frames is not None:
            frames.append(robo.image('cam_head'))

    def done(ok, reason=None, **kw):
        return dict(ok=ok, reason=reason, replies=out, actions=used(robo) - start, **kw)

    psi = math.radians(Rk['yaw_deg'])
    xr = np.array([math.cos(psi), math.sin(psi), 0.0])
    if xr[1] < 0:
        xr = -xr
    yr = np.array([-xr[1], xr[0], 0.0])
    c = np.array([Rk['centre'][0], Rk['centre'][1], 0.0])
    held_pitch = float(robo.state().arm(arm).pitch)
    kw = dict(pitch=held_pitch, yaw=heading_deg(xr), roll=0.0, gripper=robo.CLOSE)

    def tcp(lowest_above_floor, along=0.0, across=0.0):
        q = c + xr * along + yr * across
        q[2] = RACK_FLOOR_Z + lowest_above_floor
        return q

    s = robo.state().arm(arm)
    if float(s.gripper) <= 0.03:
        return done(False, 'the right hand holds nothing: the laptop has to be pinched at its hinge edge first')
    out.append(go(robo, arm, np.asarray(s.tcp_pos) + [0.0, 0.0, float(LAPTOP_DIMS[1]) / 4.0], pitch=s.pitch, yaw=s.yaw, roll=s.roll, gripper=robo.CLOSE, label='clear')); snap()
    travel = float(LAPTOP_DIMS[1])
    q = tcp(travel)
    pv = robo.preview_move([float(v) for v in q], arm=arm, path='auto', pitch=kw['pitch'], yaw=kw['yaw'], roll=0.0)
    if not (pv.get('reachable') and not pv.get('ik_error')):
        travel = float(LAPTOP_DIMS[1]) / 2.0
    out.append(go(robo, arm, tcp(travel), path='auto', label='inspect', **kw)); snap()
    if not out[-1]['reached']:
        return done(False, 'inspection pose not reached')
    off = held_offset(robo, arm)
    span = 0.5 * float(min(RACK_PLATE_DIMS))
    across = 0.0
    if off.get('ok'):
        across = -float(off['offset'] * (off['column_dir'] @ yr))
        across = float(np.clip(across, -span, span))
    out.append(dict(label='held-offset', ok=off.get('ok'), offset_mm=None if 'offset' not in off else round(off['offset'] * 1000, 1),
                    spread_mm=None if 'spread' not in off else round(off['spread'] * 1000, 1), across_mm=round(across * 1000, 1), reason=off.get('reason'),
                    travel=travel))
    out.append(glide(robo, arm, tcp(travel, across=across), step_m=0.02, label='over-rack', **kw)); snap()
    if not out[-1]['reached']:
        return done(False, 'over-rack pose not reached')

    def settle(height, label):
        """Step to a height, then cancel the arm's own sideways error read from proprioception."""
        out.append(glide(robo, arm, tcp(height, across=across), step_m=0.012, label=label, **kw))
        err = float((np.asarray(robo.state().arm(arm).tcp_pos) - tcp(height, across=across)) @ yr)
        if abs(err) > 0.001:
            out.append(go(robo, arm, tcp(height, across=across - err), label=label + '-trim', **kw))
        snap()

    base = across

    def lower_edge(label):
        """Lower edge's offset across the slot, relative to the hand (wrist view). None when not measured."""
        try:
            e = edge_view(robo, arm)
        except Exception as exc:
            e = dict(ok=False, reason='edge view error: %s' % str(exc)[:80])
        val = None
        if e.get('ok'):
            val = float(e['offset'] * (e['column_dir'] @ yr))
        out.append(dict(label=label, ok=e.get('ok'), reason=e.get('reason'), edge_mm=None if val is None else round(val * 1000, 1),
                        lean_mm=None if 'lean_mm' not in e else round(e['lean_mm'], 1), hinge_mm=None if 'hinge_mm' not in e else round(e['hinge_mm'], 1),
                        left_px=e.get('left_px'), right_px=e.get('right_px'), strip_px=e.get('strip_px'), across_mm=round(across * 1000, 1)))
        return val

    def aim(e):
        return float(np.clip(-e, -span, span))

    entered = None
    bias = 0.0
    for attempt in range(4):
        across = base
        settle(travel, 'line-up')
        free = lower_edge('edge-view')
        if free is not None and (abs(base + free) > span / 4.0 or bias):
            across = aim(free - bias)
            settle(travel, 'line-up-align')
            again = lower_edge('edge-view')
            if again is not None and abs(again - free) <= 0.006:
                free = again
                if abs(across + free - bias) > 0.004:
                    across = aim(free - bias)
                    settle(travel, 'line-up-align')
            elif again is not None:
                across = base
                settle(travel, 'line-up-reset')
                free = lower_edge('edge-view')
        elif free is None and bias:
            across = float(np.clip(base + bias, -span, span))
            settle(travel, 'line-up-align')
        lost, touch, over_slot = False, 0.0, False
        for height, label in ((RACK_WALL_TOP, 'approach-slot'),):
            settle(height, label)
            e = lower_edge('edge-view')
            over_slot = True if e is None else bool(abs(across + e - bias) <= 0.5 * float(min(RACK_PLATE_DIMS)))
            if free is None:
                continue
            if e is None or abs(e - free) > 0.009:
                lost = True
                touch = 0.0 if e is None else float(np.sign(e - free))
                break
        if not lost:
            settle(RACK_WALL_TOP, 'enter-slot')
            while abs(across - base) > 0.001:
                across = base + float(np.sign(across - base)) * max(0.0, abs(across - base) - float(min(RACK_PLATE_DIMS)) / 4.0)
                settle(RACK_WALL_TOP, 'square-up')
            e = lower_edge('edge-check')
            entered = bool(over_slot)
            if not entered and e is not None:
                touch = float(np.sign(base + e))
        else:
            entered = False
        held = float(robo.state().arm(arm).gripper) > 0.03
        out.append(dict(label='entered', attempt=attempt + 1, entered=entered, touched_on_the_way=lost, bias_mm=round(bias * 1000, 1), holding=held))
        if not held:
            across = base
            settle(travel, 'lift-empty')
            return done(False, 'laptop left the right hand during the insertion', across=across, entered=False, holding=False)
        if entered:
            break
        bias = float(np.clip(bias - (span / 4.0) * touch, -span, span))
        across = base
        settle(travel, 'lift-retry')
    if not entered:
        return done(False, 'lower edge not in the slot after four tries', across=across, entered=False)
    across = base
    settle(RACK_WALL_TOP, 'in-slot')
    g = robo.set_gripper(arm, robo.OPEN, opening=0.3)
    out.append(dict(label='loosen', opening=g.opening, actions=g.steps_used)); snap()
    g = robo.set_gripper(arm, robo.OPEN)
    out.append(dict(label='open', opening=g.opening, actions=g.steps_used))
    s = robo.state().arm(arm)
    ap = math.radians(s.pitch); ay = math.radians(s.yaw)
    axis = np.array([-math.sin(ay) * math.cos(ap), math.cos(ay) * math.cos(ap), -math.sin(ap)])
    out.append(go(robo, arm, np.asarray(s.tcp_pos) - float(LAPTOP_DIMS[1]) / 2.0 * axis, pitch=s.pitch, yaw=s.yaw, roll=s.roll, label='withdraw')); snap()
    return done(True, across=across, entered=entered)


def finish(robo):
    """Open both hands and return both arms to the start pose."""
    start = used(robo)
    out = []
    for arm in ('left', 'right'):
        if robo.state().arm(arm).gripper < 1.0:
            g = robo.set_gripper(arm, robo.OPEN)
            out.append(dict(label='open-' + arm, opening=g.opening, actions=g.steps_used))
    ended = False
    for _ in range(3):
        try:
            h = robo.home('both')
        except Exception as exc:
            ended = True
            out.append(dict(label='home', episode_ended=True, message=str(exc)[:120]))
            break
        out.append(dict(label='home', reached=bool(h.reached), error=round(float(h.max_joint_error_rad), 4), actions=h.steps_used))
        if h.reached:
            break
    try:
        spent = used(robo) - start
    except Exception:
        spent = None
    return dict(ok=bool(ended or (out and out[-1].get('reached'))), episode_ended=ended, replies=out, actions=spent)


def brief(d, drop=('mask', 'replies', 'corners', 'R', 'seg')):
    """Compact printable copy of a result dict."""
    out = {}
    for k, v in d.items():
        if k in drop:
            continue
        if isinstance(v, np.ndarray):
            v = np.round(v, 4).tolist()
        elif isinstance(v, tuple):
            v = tuple(round(float(x), 4) if isinstance(x, (float, np.floating)) else x for x in v)
        elif isinstance(v, dict):
            v = brief(v, drop)
        out[k] = v
    return out


def survey(robo):
    """Static scene measurements at the original reset, arms home and nothing occluded."""
    st = robo.state()
    at = used(robo)
    start = dict((a, np.asarray(st.arm(a).tcp_pos, float)) for a in ('left', 'right')) if at == 0 else {}
    return dict(lid=lid_top_edge(robo), stand=stand_pose(robo), headset=headset_cups(robo), start_tcp=start, at=at)


def home_if_away(robo, S, arms=('left', 'right')):
    """Send each named arm home unless its hand is already at its start position (from the reset survey)."""
    recs = []
    start = (S or {}).get('start_tcp') or {}
    for arm in arms:
        tcp = np.asarray(robo.state().arm(arm).tcp_pos, float)
        if arm in start and float(np.linalg.norm(tcp - start[arm])) == 0.0:
            continue
        for _ in range(2):
            h = robo.home(arm)
            recs.append(dict(label='home-' + arm, reached=bool(h.reached), actions=int(h.steps_used), at=used(robo)))
            if h.reached:
                break
    return recs


def laptop_untouched(robo, S, tol_m=0.025):
    """Open laptop not moved since the reset survey: the lid's top edge measured again in the head view."""
    lid0 = (S or {}).get('lid') or {}
    if not lid0.get('ok'):
        return dict(ok=None, reason='no reset lid measurement')
    lid = lid_top_edge(robo)
    if not lid.get('ok'):
        return dict(ok=False, reason='open lid not measured now', lid=lid)
    shift = float(np.linalg.norm(np.asarray(lid['top_center'][:2]) - np.asarray(lid0['top_center'][:2])))
    turn = abs((lid['yaw_deg'] - lid0['yaw_deg'] + 90.0) % 180.0 - 90.0)
    return dict(ok=bool(shift < tol_m and turn < 8.0), shift_m=round(shift, 3), turn_deg=round(turn, 1), lid=lid)


def stage_closure(robo, S, frames=None):
    """Close the lid, park the pusher arm over the rack (which measures the rack), check the laptop.

    Runs after the headphones stage: both arms are first sent home (the pushes were developed from there), then
    the open lid is measured again, so a laptop nudged during the hang is pushed where it now is.
    """
    homed = home_if_away(robo, S)
    lid = lid_top_edge(robo)
    if lid.get('ok'):
        S['lid'] = lid
    if not S['lid'].get('ok'):
        return dict(ok=False, stage='closure', reason='open lid not measured', lid=S['lid'], homed=homed)
    r = close_lid(robo, S['lid'], frames=frames)
    r['replies'] = homed + r['replies']
    rack = rack_survey(robo)
    check = lid_closed(robo, S['lid'])
    pose = closed_laptop_pose(robo)
    yaw_ok = pose.get('ok') and -25.0 <= pose['yaw_deg'] <= 25.0
    ok = bool(check.get('closed') and rack.get('ok') and yaw_ok)
    return dict(ok=ok, stage='closure', closure=r, rack=rack, lid_check=check, laptop=pose, actions=r['actions'] + rack['actions'],
                reason=None if ok else 'postcondition: lid closed %s, rack measured %s, laptop pose usable %s' % (check.get('closed'), rack.get('ok'), bool(yaw_ok)))


def stage_headphones(robo, S, frames=None):
    """Hang the headset. The stand pose comes from the reset survey; the headset is measured fresh."""
    H = headset_cups_clear(robo)
    if not H.get('ok') or not S['stand'].get('ok'):
        return dict(ok=False, stage='headphones', reason='headset or stand not measured', headset=H, stand=S['stand'])
    moved = None
    r = hang_headset(robo, H, S['stand'], frames=frames)
    total = r['actions'] + (moved['actions'] if moved else 0)
    retry = None
    if not r['ok']:
        post = [x for x in r.get('replies', []) if x.get('label') == 'post-hang']
        fell = bool(post and post[-1].get('band_top') is not None and post[-1]['band_top'][2] < 0.05)
        H2 = dict(ok=False)
        if fell or not post:
            robo.home('left')
            H2 = headset_cups_clear(robo)
        centre = np.asarray(S['stand']['centre'], float)
        if H2.get('ok') and np.linalg.norm(np.asarray(H2['mid'][:2], float) - centre[:2]) > 0.09:
            retry = hang_headset(robo, H2, S['stand'], frames=frames, own_axis='sliding out of the pinch' in str(r.get('reason')))
            total += retry['actions']
            return dict(ok=bool(retry['ok']), stage='headphones', headset=H2, relocate=moved, hang=retry, first_hang=r, retried=True,
                        direction_uncertain=True, actions=total, reason=retry.get('reason'))
    return dict(ok=bool(r['ok']), stage='headphones', headset=H, relocate=moved, hang=r, actions=total, reason=r.get('reason'))


def stage_pickup(robo, frames=None):
    """Clearance check (front lip measured and reachable), then pinch, pull, re-pinch, lift, present."""
    total = 0
    tries = []
    riser_edge = None
    for attempt in (1, 2):
        P = closed_laptop_pose(robo)
        if not P.get('ok') or not -25.0 <= P['yaw_deg'] <= 25.0:
            return dict(ok=False, stage='pickup', reason='closed laptop pose not usable', laptop=P, tries=tries, actions=total)
        if riser_edge is None:
            riser_edge = P['front'][:2]
            overhang = None
        else:
            overhang = float((riser_edge - P['front'][:2]) @ P['y_dir'][:2])
        r = pick_laptop(robo, P, frames=frames, overhang=overhang)
        total += r['actions']
        held = held_laptop_pose(robo) if r['ok'] else None
        level = bool(held and held.get('ok'))
        tries.append(dict(attempt=attempt, pick=r, level=level))
        if r['ok'] and level:
            return dict(ok=True, stage='pickup', laptop=P, pick=r, held=held, tries=tries, actions=total, reason=None)
        if attempt == 2:
            break
        hand = robo.state().arm('left')
        if float(hand.gripper) > 0.03 and float(hand.tcp_pos[2]) > LAPTOP_MID_Z + 0.03:
            back = return_to_riser(robo, P, frames=frames)
        else:
            g = robo.set_gripper('left', robo.OPEN)
            a = math.radians(hand.yaw)
            away = np.asarray(hand.tcp_pos) - float(LAPTOP_DIMS[1]) / 2.0 * np.array([-math.sin(a), math.cos(a), 0.0]) + [0, 0, float(LAPTOP_DIMS[1]) / 4.0]
            back = dict(replies=[go(robo, 'left', away, pitch=hand.pitch, yaw=hand.yaw, roll=hand.roll, gripper=robo.OPEN, label='back-out')])
            back['actions'] = back['replies'][0]['actions'] + g.steps_used
        total += back['actions']
        tries[-1]['recovery'] = back
    return dict(ok=False, stage='pickup', laptop=P, pick=r, tries=tries, actions=total,
                reason=r.get('reason') or 'laptop not held level after two attempts')


def rack_check(robo, rack):
    """Postcondition of the insertion from the head view: the laptop mask sits where a laptop standing in the rack would."""
    s = None
    for prompt in LAPTOP_PROMPTS:
        s = segment(robo, prompt)
        if s is not None:
            break
    if s is None:
        return dict(ok=False, standing=False, reason='laptop mask not found')
    K, E = cam(robo)
    c = np.array([rack['centre'][0], rack['centre'][1], RACK_FLOOR_Z + LAPTOP_DIMS[1] / 2])
    want = project(K, E, c)[0]
    rows, cols = np.nonzero(s['mask'])
    got = np.array([rows.mean(), cols.mean()])
    off = float(np.linalg.norm(got - want))
    return dict(ok=True, standing=True, offset_px=off, pixels=int(len(rows)), score=s['score'], mask=s)


def stage_placement(robo, rack, frames=None, do_finish=True):
    """Hand over to the receiver arm, insert into the rack, open hands and home."""
    Q = held_laptop_pose(robo)
    if not Q.get('ok'):
        return dict(ok=False, stage='placement', reason='presented laptop not measured', held=Q)
    h = hand_over(robo, Q, frames=frames)
    if not h['ok']:
        return dict(ok=False, stage='placement', reason=h.get('reason'), held=Q, handover=h, actions=h['actions'])
    robo.home('left')
    i = insert_laptop(robo, rack, frames=frames)
    try:
        import json
        with open('stage_trace_insert.json', 'w') as fh:
            json.dump([dict((k, (v if isinstance(v, (int, float, str, bool, type(None))) else str(v))) for k, v in r.items())
                       for r in h['replies'] + i['replies']], fh)
    except Exception:
        pass
    check = rack_check(robo, rack) if i['ok'] else None
    if not do_finish:
        ok = bool(i['ok'])
        return dict(ok=ok, stage='placement', held=Q, handover=h, insert=i, rack_check=check, finish=None,
                    actions=h['actions'] + i['actions'], reason=None if ok else i.get('reason'))
    f = finish(robo) if i['ok'] else None
    ok = bool(i['ok'] and f and f['ok'])
    return dict(ok=ok, stage='placement', held=Q, handover=h, insert=i, rack_check=check, finish=f,
                actions=h['actions'] + i['actions'] + ((f.get('actions') or 0) if f else 0), reason=None if ok else (i.get('reason') or 'finish incomplete'))


class StageRoutines:
    """Runs each chain stage's executed routine and reports its measured postconditions.

    Use one method per stage, in the task's order: headphones(), closure(),
    clearance(), pickup(), placement(), finish(). Each returns a dict with ``ok``, a ``summary`` of what was measured,
    ``images`` to look at (show them with ``show(out, display)``) and a
    ``review`` ready for ``chain.complete(review=out['review'])``. The review
    flags are filled from the routine's own measurements; pass it on only after
    looking at the images, and edit it if what you see disagrees. A routine
    that reports ``ok`` False has stopped at a safe point and says why; calling
    the same method again re-measures and retries. Nothing here ends the episode;
    it ends by itself once the task is complete.
    """

    FLAGS = dict(headphones=('headset_supported_directed', 'laptop_untouched', 'hands_disengaged'),
                 closure=('closed_supported_laptop', 'earlier_placements_preserved', 'hands_disengaged'),
                 clearance=('supported_accessible_edge', 'finger_corridor', 'earlier_placements_preserved'),
                 pickup=('retained_observable_laptop', 'usable_transfer_or_support_route', 'earlier_placements_preserved'),
                 placement=('canonical_rack_support', 'hands_disengaged', 'earlier_placements_preserved'))

    def __init__(self, robo):
        self.robo = robo
        self.S = None
        self.rack = None
        self.laptop_after_closure = None
        self.pushed = False
        self.log = {}

    def _review(self, phase, measured, tag):
        ids = ['auto-%s-cam_head-%d' % (tag, used(self.robo))]
        review = dict(action_count=used(self.robo), observation_ids=ids)
        for flag in self.FLAGS[phase]:
            review[flag] = bool(measured.get(flag))
        review['evidence'] = '; '.join('%s=%s' % (k, measured.get(k)) for k in self.FLAGS[phase])
        return review

    def _head(self, masks=(), points=(), lines=()):
        return overlay(self.robo, 'cam_head', masks=[m for m in masks if m is not None], points=points, lines=lines, scale=1)


    def _out(self, phase, ok, reason, measured, summary, images, **extra):
        out = dict(stage=phase, ok=bool(ok), reason=reason, measured=measured, summary=summary, images=images,
                   review=self._review(phase, measured, phase) if phase in self.FLAGS else None,
                   episode_actions=used(self.robo), **extra)
        self.log[phase] = dict(ok=out['ok'], reason=reason, measured=measured, episode_actions=out['episode_actions'])
        return out

    @staticmethod
    def show(out, display):
        """Display the routine's evidence images and print its compact result."""
        for im in out.get('images') or ():
            display(im)
        print({k: out[k] for k in ('stage', 'ok', 'reason', 'measured', 'episode_actions')})
        print(out.get('summary'))

    @staticmethod
    def complete(chain, out):
        """Record a stage whose routine reported ok as complete in the chain (headphones: direction review first).

        Does nothing and says so when the routine did not report ok. Returns the chain's reply.
        """
        if not out.get('ok') or out.get('review') is None:
            return dict(status='not_completed', reason='the routine did not report ok: look at the evidence and recover', stage=out.get('stage'))
        reply = {}
        if out.get('stage') == 'headphones' and out.get('direction') is not None:
            reply['direction'] = chain.review_headphone_direction(**out['direction']).get('status')
        done = chain.complete(review=out['review'])
        reply.update(status=done.get('status'), phase=done.get('phase'), completed=done.get('completed'), action_count=done.get('action_count'))
        return reply

    def _headset_hung(self):
        if self.S is None or not self.S['stand'].get('ok'):
            return None
        h = hung_offset(self.robo, self.S['stand'], self.S['stand']['mask']['mask'])
        return bool(h.get('ok') and h['offset_px'] <= 30.0)

    def headphones(self):
        """Hang the headset with the laptop still open: right arm parked over the rack first (it measures the rack and
        is the side-view camera), then left-arm earcup pinch, side look from the right arm, low approach over the cradle."""
        if self.S is None:
            self.S = survey(self.robo)
        if not self.S['stand'].get('ok'):
            self.S = dict(self.S, stand=stand_pose(self.robo))
        if not self.S['stand'].get('ok'):
            return self._out('headphones', False, 'stand not measured in the head view', {}, None, [self._head()])
        if self.rack is None:
            rk = rack_survey(self.robo)
            self.rack = rk if rk.get('ok') else None
        h = stage_headphones(self.robo, self.S)
        lap = laptop_untouched(self.robo, self.S)
        post = [r for r in (h.get('hang') or {}).get('replies', []) if r.get('label') == 'post-hang']
        measured = dict(headset_supported_directed=bool(h['ok']), laptop_untouched=bool(lap.get('ok') is not False),
                        hands_disengaged=True, lid_shift_m=lap.get('shift_m'))
        St = self.S['stand']
        count = used(self.robo)
        ids = ['auto-headphones-cam_head-%d' % count]
        frame = dict(rotation_world=np.asarray(St['R']).tolist(), action_count=count, observation_ids=ids)
        direction = dict(held=frame, target=dict(frame), uncertainty_deg=15.0,
                         identity=dict(method='visual_correspondence', anchor_observation_ids=['auto-reset-cam_head-0'], observation_ids=ids,
                                       description='The earcup that lay on the robot-left side at reset was pinched by the left arm and held without '
                                                   'regrasp until release, so it hangs on the stand\'s negative-x side and the other earcup on the positive-x '
                                                   'side; the headset x axis therefore runs along the stand\'s long axis in the same direction. Check both '
                                                   'earcups on either side of the stand in the displayed head view before using this record.'))
        out = self._out('headphones', h['ok'], h.get('reason'), measured, dict(post_hang=post[-1] if post else None, actions=h.get('actions'),
                        relocated=bool(h.get('relocate')), retried_after_fall=bool(h.get('retried'))),
                        [self._head(masks=[(lap.get('lid') or {}).get('mask')])], direction=direction)
        out['review']['observation_ids'] = ids
        return out

    def closure(self):
        """After the hang: both arms home, close the lid with the right arm (left hand braces the base), park the right
        arm over the rack (which measures the rack), measure the closed laptop, check the headset still hangs."""
        if self.S is None:
            self.S = survey(self.robo)
        if self.pushed:
            lid = lid_top_edge(self.robo)
            lap = closed_laptop_pose(self.robo)
            if lid.get('ok') and not (lap.get('ok') and -25.0 <= lap.get('yaw_deg', 99.0) <= 25.0):
                self.S = dict(self.S, lid=lid)
            else:
                rack = self.rack if self.rack is not None else rack_survey(self.robo)
                self.rack = rack if rack.get('ok') else self.rack
                hung = self._headset_hung()
                closed = bool(lap.get('ok'))
                measured = dict(closed_supported_laptop=closed, earlier_placements_preserved=bool(hung is not False), hands_disengaged=True,
                                rack_measured=bool(self.rack is not None))
                if closed:
                    self.laptop_after_closure = lap
                ok = closed and measured['rack_measured']
                return self._out('closure', ok, None if ok else 'no open lid measured and no closed laptop outlined: look at the head view before any motion',
                                 measured, dict(repeat_look_only=True, laptop=brief(lap), open_lid_seen=bool(lid.get('ok'))),
                                 [self._head(masks=[lap.get('mask')])])
        self.pushed = True
        c = stage_closure(self.robo, self.S)
        self.rack = c.get('rack') if (c.get('rack') or {}).get('ok') else self.rack
        lap = c.get('laptop') or {}
        if lap.get('ok'):
            self.laptop_after_closure = lap
        hung = self._headset_hung()
        measured = dict(closed_supported_laptop=bool((c.get('lid_check') or {}).get('closed') and lap.get('ok')),
                        earlier_placements_preserved=bool(hung is not False), hands_disengaged=True,
                        rack_measured=bool((c.get('rack') or {}).get('ok')))
        pts = [lap['front'], lap['hinge']] if lap.get('ok') else []
        images = [self._head(masks=[lap.get('mask')], points=pts)]
        summary = dict(lid_check=c.get('lid_check'), laptop=brief(lap), rack=brief((c.get('rack') or {}).get('fine') or {}), actions=c.get('actions'))
        return self._out('closure', c['ok'], c.get('reason'), measured, summary, images)

    def clearance(self):
        """Measure the closed laptop on the riser and check the front-lip pinch poses are reachable. No motion."""
        P = closed_laptop_pose(self.robo)
        reach = False
        if P.get('ok') and -25.0 <= P['yaw_deg'] <= 25.0:
            x, y = P['x_dir'], P['y_dir']
            f = np.array([P['front'][0], P['front'][1], LAPTOP_MID_Z])
            yaw = heading_deg(y)
            reach = True
            pitch = float(self.robo.state().arm('left').pitch)
            for q in (f - y * (float(LAPTOP_DIMS[1]) / 2.0) + [0, 0, float(LAPTOP_DIMS[1]) / 4.0], f):
                pv = self.robo.preview_move([float(v) for v in q], arm='left', path='auto', pitch=pitch, yaw=yaw, roll=90.0)
                reach = reach and bool(pv.get('reachable')) and not pv.get('ik_error')
        hung = self._headset_hung()
        measured = dict(supported_accessible_edge=bool(P.get('ok') and -25.0 <= P.get('yaw_deg', 99) <= 25.0), finger_corridor=bool(reach),
                        earlier_placements_preserved=bool(hung is not False))
        ok = measured['supported_accessible_edge'] and measured['finger_corridor']
        pts = [P['front'], P['hinge']] if P.get('ok') else []
        return self._out('clearance', ok, None if ok else 'front lip not measured or not reachable', measured, dict(laptop=brief(P)),
                         [self._head(masks=[P.get('mask')], points=pts)])

    def pickup(self):
        """Pinch the front lip, work the laptop forward, re-pinch deeper, lift and present it level."""
        k = stage_pickup(self.robo)
        held = k.get('held') or {}
        hung = self._headset_hung()
        measured = dict(retained_observable_laptop=bool(k['ok'] and held.get('ok')), usable_transfer_or_support_route=bool(k['ok']),
                        earlier_placements_preserved=bool(hung is not False))
        pts = [held['front'], held['hinge']] if held.get('ok') else []
        return self._out('pickup', k['ok'], k.get('reason'), measured, dict(attempts=len(k.get('tries', [])), held=brief(held), actions=k.get('actions')),
                         [self._head(masks=[held.get('mask')], points=pts)])

    def placement(self):
        """Hand the laptop to the right arm, insert it into the rack hinge edge up, let go and withdraw. Left arm goes home."""
        if self.rack is None:
            self.rack = rack_survey(self.robo)
        pl = stage_placement(self.robo, self.rack, do_finish=False)
        chk = pl.get('rack_check') or {}
        hung = self._headset_hung()
        measured = dict(canonical_rack_support=bool(pl['ok'] and chk.get('standing')), hands_disengaged=bool(pl['ok']),
                        earlier_placements_preserved=bool(hung is not False), rack_offset_px=None if 'offset_px' not in chk else round(chk['offset_px'], 1))
        standing = bool(chk.get('standing'))
        ok = bool(pl['ok'] and standing)
        reason = pl.get('reason') or (None if standing else 'laptop not measured standing in the rack (head view)')
        return self._out('placement', ok, reason, measured, dict(actions=pl.get('actions'), entered=(pl.get('insert') or {}).get('entered')),
                         [self._head(masks=[chk.get('mask')])])

    def recheck(self, phase):
        """Measure a stage's exit conditions again from the head view, without moving. Same result shape as the stage call.

        Use it when anything moved after a stage call (the review's action count
        must be the current one), or to look again before deciding. It does not
        repeat the stage.
        """
        hung = self._headset_hung()
        if phase == 'closure':
            lap = closed_laptop_pose(self.robo)
            closed = lid_closed(self.robo, self.S['lid']) if self.S and self.S['lid'].get('ok') else dict(closed=bool(lap.get('ok')))
            measured = dict(closed_supported_laptop=bool(closed.get('closed') and lap.get('ok')), earlier_placements_preserved=bool(hung is not False),
                            hands_disengaged=True)
            ok = measured['closed_supported_laptop']
            return self._out('closure', ok, None if ok else 'closed laptop not measured', measured, dict(laptop=brief(lap)),
                             [self._head(masks=[lap.get('mask')])])
        if phase == 'headphones':
            lap = laptop_untouched(self.robo, self.S) if not self.pushed else dict(ok=None)
            measured = dict(headset_supported_directed=bool(hung), laptop_untouched=bool(lap.get('ok') is not False), hands_disengaged=True)
            return self._out('headphones', bool(hung), None if hung else 'headset not measured hanging on the stand (head view)', measured, None,
                             [self._head()])
        if phase == 'clearance':
            return self.clearance()
        if phase == 'pickup':
            held = held_laptop_pose(self.robo)
            measured = dict(retained_observable_laptop=bool(held.get('ok')), usable_transfer_or_support_route=bool(held.get('ok')),
                            earlier_placements_preserved=bool(hung is not False))
            return self._out('pickup', bool(held.get('ok')), None if held.get('ok') else 'presented laptop not measured', measured, dict(held=brief(held)),
                             [self._head(masks=[held.get('mask')])])
        if phase == 'placement':
            chk = rack_check(self.robo, self.rack) if self.rack is not None else {}
            measured = dict(canonical_rack_support=bool(chk.get('standing')), hands_disengaged=True, earlier_placements_preserved=bool(hung is not False),
                            rack_offset_px=None if 'offset_px' not in chk else round(chk['offset_px'], 1))
            return self._out('placement', bool(chk.get('standing')), None if chk.get('standing') else 'laptop not measured standing in the rack', measured, None,
                             [self._head(masks=[chk.get('mask')])])
        raise ValueError('phase is one of headphones, closure, clearance, pickup, placement')

    def finish(self):
        """Open both hands and return both arms to the start pose. The episode may end by itself during this."""
        f = finish(self.robo)
        return dict(stage='final_review', ok=bool(f['ok']), episode_ended=bool(f.get('episode_ended')), replies=f['replies'])


_ROUTINES = {}


def routines(robo):
    """The StageRoutines object for this episode (created once, kept between cells)."""
    if 'r' not in _ROUTINES:
        _ROUTINES['r'] = StageRoutines(robo)
    return _ROUTINES['r']
